async function PICK_ONE(tbl) {
  let length = 0, cnt = 0, rnd = 0, msg = 0, rfrob = 0;
  length = get(tbl, 0);
  cnt = get(tbl, 1);
  length = length - 1;
  tbl = tbl + 2;
  rfrob = tbl + (cnt * 2);
  rnd = random(length - cnt);
  msg = get(rfrob, rnd);
  put(rfrob, rnd, get(rfrob, 1));
  put(rfrob, 1, msg);
  cnt = cnt + 1;
  if (cnt == length) {
    cnt = 0;
  }
  put(tbl, 0, cnt);
  return msg;
}

async function GO() {
  restart: for (;;) {
    await OPENING_SCREEN();
    await V_LOOK();
    await MAIN_LOOP();
    continue restart;
  }
}

async function MAIN_LOOP() {
  let trash = 0;
  for (;;) {
    trash = await MAIN_LOOP_1();
  }
}

async function MAIN_LOOP_1() {
  let icnt = 0, ocnt = 0, num = 0, cnt = 0, obj = 0, tbl = 0, v_ = 0, ptbl = 0, obj1 = 0, tmp = 0;
  cnt = 0;
  obj = false;
  ptbl = true;
  if (g.P_WON = await PARSER()) {
    icnt = get(g.P_PRSI, P_MATCHLEN);
    ocnt = get(g.P_PRSO, P_MATCHLEN);
    if (g.P_IT_OBJECT && (await ACCESSIBLE$(g.P_IT_OBJECT))) {
      tmp = false;
      loop1: for (;;) {
        if ((cnt = cnt + 1) > icnt) {
          break loop1;
        } else {
          if (eq(get(g.P_PRSI, cnt), IT)) {
            put(g.P_PRSI, cnt, g.P_IT_OBJECT);
            tmp = true;
            break loop1;
          }
        }
      }
      if (!tmp) {
        cnt = 0;
        loop2: for (;;) {
          if ((cnt = cnt + 1) > ocnt) {
            break loop2;
          } else {
            if (eq(get(g.P_PRSO, cnt), IT)) {
              put(g.P_PRSO, cnt, g.P_IT_OBJECT);
              break loop2;
            }
          }
        }
      }
      cnt = 0;
    }
    num = ocnt == 0 ? ocnt : (ocnt > 1 ? (tbl = g.P_PRSO, icnt == 0 ? (obj = false) : (obj = get(g.P_PRSI, 1)), ocnt) : (icnt > 1 ? (ptbl = false, tbl = g.P_PRSI, obj = get(g.P_PRSO, 1), icnt) : 1));
    if (!obj && (icnt == 1)) {
      obj = get(g.P_PRSI, 1);
    }
    if ((g.PRSA == V.WALK) && g.PRSO) {
      v_ = await PERFORM_PRSA(g.PRSO);
    } else if (num == 0) {
      if ((getb(g.P_SYNTAX, P_SBITS) & P_SONUMS) == 0) {
        v_ = await PERFORM_PRSA();
        g.PRSO = false;
      } else {
        tell("There isn't anything to ");
        tmp = get(g.P_ITBL, P_VERBN);
        if (isVerb(V.TELL)) {
          tell("talk to");
        } else if (g.P_OFLAG || g.P_MERGED) {
          printB(get(tmp, 0));
        } else {
          await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
        }
        tell("!\n");
        v_ = false;
        await STOP();
      }
    } else {
      g.P_NOT_HERE = 0;
      g.P_MULT = false;
      if (num > 1) {
        g.P_MULT = true;
      }
      tmp = false;
      loop3: for (;;) {
        if ((cnt = cnt + 1) > num) {
          if (g.P_NOT_HERE > 0) {
            tell("[The ");
            if (!(g.P_NOT_HERE == num)) {
              tell("other ");
            }
            tell("object");
            if (!(g.P_NOT_HERE == 1)) {
              tell("s");
            }
            tell(" that you mentioned ");
            if (!(g.P_NOT_HERE == 1)) {
              tell("are");
            } else {
              tell("is");
            }
            tell("n't here.]\n");
          } else if (!tmp) {
            await REFERRING();
          }
          break loop3;
        } else {
          if (ptbl) {
            obj1 = get(g.P_PRSO, cnt);
          } else {
            obj1 = get(g.P_PRSI, cnt);
          }
          g.PRSO = ptbl ? obj1 : obj;
          g.PRSI = ptbl ? obj : obj1;
          if ((num > 1) || eq(get(get(g.P_ITBL, P_NC1), 0), W.ALL, W.EVERYTHING)) {
            if (await DONT_ALL(obj1)) {
              continue loop3;
            } else {
              if (obj1 == IT) {
                await DPRINT(g.P_IT_OBJECT);
              } else if (obj1 == HIM) {
                await DPRINT(g.P_HIM_OBJECT);
              } else if (obj1 == HER) {
                await DPRINT(g.P_HER_OBJECT);
              } else {
                await DPRINT(obj1);
              }
              tell(": ");
            }
          }
          tmp = true;
          v_ = await PERFORM_PRSA(g.PRSO, g.PRSI);
          if (v_ == M_FATAL) {
            break loop3;
          }
        }
      }
    }
    if (v_ == M_FATAL) {
      g.P_CONT = false;
    }
    if ((await CLOCKER_VERB$()) && !(isVerb(V.TELL)) && g.P_WON) {
      v_ = await apply(getProp(g.HERE, P.ACTION), M_END);
    }
  } else {
    g.P_CONT = false;
  }
  if (g.P_WON) {
    if (await CLOCKER_VERB$()) {
      v_ = await CLOCKER();
    }
    g.P_PRSA_WORD = false;
    g.PRSA = false;
    g.PRSO = false;
    g.PRSI = false;
  }
  if (g.AWAITING_FAKE_ORPHAN && !g.P_OFLAG) {
    return await ORPHAN_VERB();
  } else {
    return false;
  }
}

async function DONT_ALL(obj1) {
  let l = loc(obj1);
  if (obj1 == NOT_HERE_OBJECT) {
    g.P_NOT_HERE = g.P_NOT_HERE + 1;
    return true;
  } else if (isVerb(V.TAKE) && g.PRSI && !(loc(g.PRSO) == g.PRSI)) {
    return true;
  } else if (!(await ACCESSIBLE$(obj1))) {
    return true;
  } else if (g.P_GETFLAGS == P_ALL) {
    if (g.PRSI && (g.PRSO == g.PRSI)) {
      return true;
    } else if (isVerb(V.TAKE)) {
      if (!(hasFlag(obj1, TAKEBIT)) && !(hasFlag(obj1, TRYTAKEBIT))) {
        return true;
      } else if (!(l == g.WINNER || l == g.HERE || l == g.PRSI) && !(l == loc(g.WINNER))) {
        if (hasFlag(l, SURFACEBIT) && !(hasFlag(l, TAKEBIT))) {
          return false;
        } else {
          return true;
        }
      } else if (!g.PRSI && (await ULTIMATELY_IN$(g.PRSO))) {
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.DROP, V.PUT, V.PUT_ON, V.GIVE, V.SGIVE) && !(loc(obj1) == g.WINNER)) {
      return true;
    } else if (isVerb(V.DROP, V.PUT, V.PUT_ON, V.GIVE, V.SGIVE) && hasFlag(obj1, WORNBIT)) {
      return true;
    } else if (isVerb(V.PUT, V.PUT_ON) && !(loc(g.PRSO) == g.WINNER) && (await ULTIMATELY_IN$(g.PRSO, g.PRSI))) {
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function CLOCKER_VERB$() {
  if (isVerb(V.VERSION, V.SAVE, V.RESTORE, V.RESTART, V.QUIT, V.SCRIPT, V.UNSCRIPT, V.BRIEF, V.SUPER_BRIEF, V.VERBOSE, V.HINT, V.$ISL)) {
    return false;
  } else {
    return true;
  }
}

async function FAKE_ORPHAN(it_was_used = false) {
  let tmp = 0;
  await ORPHAN(g.P_SYNTAX, false);
  tmp = get(g.P_OTBL, P_VERBN);
  tell("[Be specific: Wh");
  if (it_was_used) {
    tell("at object");
  } else {
    tell("o");
  }
  tell(" do you want to ");
  if (tmp == 0) {
    tell("tell");
  } else if (getb(g.P_VTBL, 2) == 0) {
    printB(get(tmp, 0));
  } else {
    await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    putb(g.P_VTBL, 2, 0);
  }
  g.P_OFLAG = true;
  g.P_WON = false;
  await PREP_PRINT(getb(g.P_SYNTAX, P_SPREP1));
  tell("?]\n");
  return true;
}

async function PERFORM_PRSA(o = false, i = false) {
  return await PERFORM(g.PRSA, o, i);
}

async function PERFORM(a_, o = false, i = false) {
  let v_ = 0, oa = 0, oo = 0, oi = 0;
  oa = g.PRSA;
  oo = g.PRSO;
  oi = g.PRSI;
  g.PRSA = a_;
  if ((IT == o || IT == i) && !(a_ == V.WALK)) {
    if (await VISIBLE$(g.P_IT_OBJECT)) {
      if (IT == o) {
        o = g.P_IT_OBJECT;
      } else {
        i = g.P_IT_OBJECT;
      }
    } else {
      if (!i) {
        await FAKE_ORPHAN(true);
      } else {
        await REFERRING();
      }
      return M_FATAL;
    }
  }
  if ((HIM == o || HIM == i) && !(a_ == V.WALK)) {
    if (await VISIBLE$(g.P_HIM_OBJECT)) {
      if (HIM == o) {
        o = g.P_HIM_OBJECT;
      } else {
        i = g.P_HIM_OBJECT;
      }
    } else {
      if (!i) {
        await FAKE_ORPHAN();
      } else {
        await REFERRING(true);
      }
      return M_FATAL;
    }
  }
  if ((HER == o || HER == i) && !(a_ == V.WALK)) {
    if (await VISIBLE$(g.P_HER_OBJECT)) {
      if (HER == o) {
        o = g.P_HER_OBJECT;
      } else {
        i = g.P_HER_OBJECT;
      }
    } else {
      if (!i) {
        await FAKE_ORPHAN();
      } else {
        await REFERRING(true);
      }
      return M_FATAL;
    }
  }
  g.PRSO = o;
  g.PRSI = i;
  if ((!(a_ == V.WALK) && (NOT_HERE_OBJECT == g.PRSO || NOT_HERE_OBJECT == g.PRSI) && (v_ = (await D_APPLY("Not Here", NOT_HERE_OBJECT_F.id))))) {
    g.P_WON = false;
  } else {
    o = g.PRSO;
    i = g.PRSI;
    await THIS_IS_IT(g.PRSI);
    await THIS_IS_IT(g.PRSO);
    if ((v_ = (await D_APPLY("Actor", getProp(g.WINNER, P.ACTION))))) {
    } else if ((v_ = (await D_APPLY("M-Beg", get(g.SCENARIO_TBL, g.SCENARIO), M_BEG)))) {
    } else if ((v_ = (await D_APPLY("M-Beg", getProp(g.HERE, P.ACTION), M_BEG)))) {
    } else if ((v_ = (await D_APPLY("Preaction", get(g.PREACTIONS, a_))))) {
    } else if ((i && (v_ = (await D_APPLY("PRSI", getProp(i, P.ACTION)))))) {
    } else if ((o && (g.P_WALK_DIR == 0) && (v_ = (await D_APPLY("PRSO", getProp(o, P.ACTION)))))) {
    } else if (v_ = await D_APPLY(false, get(g.ACTIONS, a_))) {
    }
  }
  g.PRSA = oa;
  g.PRSO = oo;
  g.PRSI = oi;
  return v_;
}

async function D_APPLY(str, fcn, foo = false) {
  let res = 0;
  if (!fcn) {
    return false;
  } else {
    res = foo ? (await apply(fcn, foo)) : (await apply(fcn));
    return res;
  }
}

async function NOISY_VERB$() {
  if (isVerb(V.MUNG, V.YELL) || isVerb(V.ALARM, V.KNOCK, V.KICK) || isVerb(V.KILL, V.HIT, V.CALL)) {
    return true;
  } else {
    return false;
  }
}

async function QUIET_VERB$() {
  if (!(await CLOCKER_VERB$()) || isVerb(V.EAT, V.DRINK) || isVerb(V.LOOK, V.EXAMINE, V.WATCH) || isVerb(V.INVENTORY, V.FIND, V.HIDE) || isVerb(V.LOOK_INSIDE, V.LOOK_UP, V.LOOK_DOWN) || isVerb(V.SMELL, V.COUNT, V.READ) || isVerb(V.WAVE, V.WAIT) || isVerb(V.SAVE, V.RESTORE, V.RESET) || isVerb(V.TAKE, V.DROP, V.PUT) || isVerb(V.OIL, V.OPEN, V.FAST_TIME) || isVerb(V.SLOW_TIME) || (isVerb(V.PUSH) && (await ULTIMATELY_IN$(g.PRSO, g.WINNER)))) {
    return true;
  } else {
    return false;
  }
}

async function CLOCKER() {
  let e = 0, tick = 0, rtn = 0, flg = false, q$ = false, owinner = 0;
  if (g.CUT_DETECTED && (g.CLOCK_TIME > g.CUT_DETECTED) && !g.CUT_VIGILANCE) {
    g.CUT_VIGILANCE = true;
  } else if ((g.HERE == HUT_STORAGE || g.HERE == HUT_BEDROOM) && (loc(HUT_MAN) == HUT_LIVING) && !(isVerb(V.WALK)) && !(await QUIET_VERB$())) {
    highlight(H_BOLD);
    crlf();
    (await JIGS_UP("That last action of yours has alerted the owner of your presence. He calmly walks in, gun in hand, and places a call to the border patrol who quickly arrive to take you into custody."));
    return true;
  } else if (hasFlag(g.HERE, GVIEWBIT) && !(isVerb(V.WALK))) {
    tick = await GUARD_DISTANCE();
    if ((g.VIGILANCE || g.CUT_VIGILANCE) && (g.TOWER_DESTROYED || prob(30)) && !g.GUARD_CHASE) {
      crlf();
      tell("One of the guards, more alert due");
      if (g.VIGILANCE) {
        tell(" to the recent explosion");
      } else {
        tell(", perhaps, to the belated detection of voltage loss in the fence");
      }
      tell(", notices you, and calls out to the other guards, who rapidly surround you and take you into custody.");
      (await JIGS_UP(" "));
      return true;
    } else if ((((await NOISY_VERB$()) && (tick < 40)) || (isVerb(V.CUT) && (tick < 25))) && !g.GUARD_CHASE) {
      crlf();
      (await JIGS_UP("You've made enough noise to attract the guard's attention! He fires a warning shot, alerting the other guards, who rapidly approach with their weapons drawn..."));
      return true;
    } else if (!(await QUIET_VERB$()) && (await GUARDS_FACING_PLAYER$()) && (tick < 70) && prob(div(100 - tick, 4)) && !g.GUARD_CHASE) {
      crlf();
      (await JIGS_UP("One of the guards notices you and fires a warning shot. An alarm sounds, and you are rapidly surrounded by border guards..."));
      return true;
    }
  }
  await I_CLOCKER(g.CLOCK_MOVE);
  if (g.SL_WATCH || g.G_WATCH) {
    await UPDATE_CHRONOGRAPH(0, true);
    await UPDATE_TIME();
  }
  g.CLOCK_MOVE = CLOCK_DEFAULT;
  return true;
}

async function ABS(n_) {
  if (!(n_ < 0)) {
    return n_;
  } else {
    return 0 - n_;
  }
}

async function TOO_LATE() {
  tell("That's already been done.\n");
  return true;
}

async function CHRONOGRAPH_TELL() {
  let n_ = 0;
  n_ = div(mod(g.CHRONOGRAPH_TIME, 3600), 60);
  if (n_ > 59) {
    n_ = n_ - 60;
  }
  if (n_ < 10) {
    tell("0");
  }
  tell(N(n_), ":");
  n_ = mod(g.CHRONOGRAPH_TIME, 60);
  if (n_ < 10) {
    tell("0");
  }
  tell(N(n_));
  return true;
}

