async function GET_OBJECT(tbl, vrb = true) {
  let bits = 0, len = 0, xbits = 0, tlen = 0, gcheck = false, olen = 0, obj = 0;
  xbits = g.P_SLOCBITS;
  tlen = get(tbl, P_MATCHLEN);
  if (btst(g.P_GETFLAGS, P_INHIBIT)) {
    return true;
  }
  if (!g.P_NAM && g.P_ADJ && (await WT$(g.P_ADJ, PS$OBJECT))) {
    g.P_NAM = g.P_ADJ;
    g.P_ADJ = false;
  } else if (g.P_ADJ && (bits = await WT$(g.P_ADJ, PS$DIRECTION, P1$DIRECTION))) {
    g.P_DIRECTION = bits;
  }
  if (!g.P_NAM && !g.P_ADJ && !(g.P_GETFLAGS == P_ALL) && (g.P_GWIMBIT == 0)) {
    if (vrb) {
      await NOUN_MISSING();
    }
    return false;
  }
  if (!(g.P_GETFLAGS == P_ALL) || (g.P_SLOCBITS == 0)) {
    g.P_SLOCBITS = -1;
  }
  loop1: for (;;) {
    if (gcheck) {
      await GLOBAL_CHECK(tbl);
    } else {
      clearFlag(PROTAGONIST, TRANSBIT);
      await DO_SL(g.HERE, SOG, SIR, tbl);
      setFlag(PROTAGONIST, TRANSBIT);
      await DO_SL(PROTAGONIST, SH, SC, tbl);
    }
    len = get(tbl, P_MATCHLEN) - tlen;
    if (btst(g.P_GETFLAGS, P_ALL)) {
    } else if (btst(g.P_GETFLAGS, P_ONE) && !(len == 0)) {
      if (!(len == 1)) {
        put(tbl, 1, get(tbl, random(len)));
        tell("[How about the ");
        printD(get(tbl, 1));
        tell("?]\n");
      }
      put(tbl, P_MATCHLEN, 1);
    } else if ((len > 1) || ((len == 0) && !(g.P_SLOCBITS == (-1)))) {
      if (g.P_SLOCBITS == (-1)) {
        g.P_SLOCBITS = xbits;
        olen = len;
        put(tbl, P_MATCHLEN, get(tbl, P_MATCHLEN) - len);
        continue loop1;
      } else {
        put(g.P_NAMW, g.P_PHR, g.P_NAM);
        put(g.P_ADJW, g.P_PHR, g.P_ADJ);
        if (len == 0) {
          len = olen;
        }
        if (g.P_NAM && (obj = get(tbl, tlen + 1)) && (obj = await apply(getProp(obj, P.GENERIC)))) {
          if (obj == NOT_HERE_OBJECT) {
            return false;
          }
          put(tbl, 1, obj);
          put(tbl, P_MATCHLEN, 1);
          g.P_NAM = false;
          g.P_ADJ = false;
          return true;
        } else if (vrb && !(g.WINNER == PROTAGONIST)) {
          await WHICH_PRINT(tlen, len, tbl);
          return false;
        } else if (vrb && g.P_NAM) {
          await WHICH_PRINT(tlen, len, tbl);
          g.P_ACLAUSE = tbl == g.P_PRSO ? P_NC1 : P_NC2;
          g.P_AADJ = g.P_ADJ;
          g.P_ANAM = g.P_NAM;
          await ORPHAN(false, false);
          g.P_OFLAG = true;
        } else if (vrb) {
          await NOUN_MISSING();
        }
        g.P_NAM = false;
        g.P_ADJ = false;
        return false;
      }
    } else if ((len == 0) && gcheck) {
      put(g.P_NAMW, g.P_PHR, g.P_NAM);
      put(g.P_ADJW, g.P_PHR, g.P_ADJ);
      if (vrb) {
        g.P_SLOCBITS = xbits;
        await OBJ_FOUND(NOT_HERE_OBJECT, tbl);
        g.P_XNAM = g.P_NAM;
        g.P_XADJ = g.P_ADJ;
        g.P_NAM = false;
        g.P_ADJ = false;
        return true;
      }
      g.P_NAM = false;
      g.P_ADJ = false;
      return false;
    } else if (len == 0) {
      gcheck = true;
      continue loop1;
    }
    g.P_SLOCBITS = xbits;
    put(g.P_NAMW, g.P_PHR, g.P_NAM);
    put(g.P_ADJW, g.P_PHR, g.P_ADJ);
    g.P_NAM = false;
    g.P_ADJ = false;
    return true;
  }
}

async function MOBY_FIND(tbl) {
  let obj = 1, len = 0, foo = 0, nam = 0, adj = 0;
  nam = g.P_NAM;
  adj = g.P_ADJ;
  g.P_NAM = g.P_XNAM;
  g.P_ADJ = g.P_XADJ;
  put(tbl, P_MATCHLEN, 0);
  loop1: for (;;) {
    loop2: for (;;) {
      if (!(loc(obj) == ROOMS) && (foo = await THIS_IT$(obj))) {
        foo = await OBJ_FOUND(obj, tbl);
      }
      if (++obj > LAST_OBJECT) {
        break loop2;
      }
    }
    break loop1;
  }
  if (eq(len = get(tbl, P_MATCHLEN), 1)) {
    g.P_MOBY_FOUND = get(tbl, 1);
  }
  g.P_NAM = nam;
  g.P_ADJ = adj;
  return len;
}

async function WHICH_PRINT(tlen, len, tbl) {
  let obj = 0, rlen = 0;
  if (len == 0) {
    await REFERRING();
    return true;
  }
  rlen = len;
  if (!(g.WINNER == PROTAGONIST)) {
    tell("\"I don't understand ");
  } else {
    tell("[Which");
    if (g.P_OFLAG || g.P_MERGED || g.P_AND) {
      tell(" ");
      printB(g.P_NAM);
    } else if (tbl == g.P_PRSO) {
      await CLAUSE_PRINT(P_NC1, P_NC1L, false);
    } else {
      await CLAUSE_PRINT(P_NC2, P_NC2L, false);
    }
    tell(" do you mean, ");
  }
  loop1: for (;;) {
    tlen = tlen + 1;
    obj = get(tbl, tlen);
    if (!(hasFlag(obj, NARTICLEBIT))) {
      tell("the ");
    }
    await DPRINT(obj);
    if (len == 2) {
      if (!(rlen == 2)) {
        tell(",");
      }
      tell(" or ");
    } else if (len > 2) {
      tell(", ");
    }
    if ((len = len - 1) < 1) {
      break loop1;
    }
  }
  if (!(g.WINNER == PROTAGONIST)) {
    tell(".\"\n");
    return true;
  } else {
    tell("?]\n");
    return true;
  }
}

async function GLOBAL_CHECK(tbl) {
  let len = 0, rmg = 0, rmgl = 0, cnt = 0, obj = 0, obits = 0, foo = 0;
  len = get(tbl, P_MATCHLEN);
  obits = g.P_SLOCBITS;
  if (rmg = getPropAddr(g.HERE, P.GLOBAL)) {
    rmgl = div(propSize(rmg), 2) - 1;
    loop1: for (;;) {
      if (await THIS_IT$(obj = get(rmg, cnt))) {
        await OBJ_FOUND(obj, tbl);
      } else if ((obj = first(obj)) && (await THIS_IT$(obj))) {
        await OBJ_FOUND(obj, tbl);
      }
      if (++cnt > rmgl) {
        break loop1;
      }
    }
  }
  if (eq(get(tbl, P_MATCHLEN), len)) {
    g.P_SLOCBITS = -1;
    await DO_SL(GLOBAL_OBJECTS, 1, 1, tbl);
    return g.P_SLOCBITS = obits;
  } else {
    return false;
  }
}

async function DO_SL(obj, bit1, bit2, tbl, moby_flag = false) {
  let bts = 0;
  if (btst(g.P_SLOCBITS, bit1 + bit2)) {
    return await SEARCH_LIST(obj, tbl, P_SRCALL, moby_flag);
  } else {
    if (btst(g.P_SLOCBITS, bit1)) {
      return await SEARCH_LIST(obj, tbl, P_SRCTOP, moby_flag);
    } else if (btst(g.P_SLOCBITS, bit2)) {
      return await SEARCH_LIST(obj, tbl, P_SRCBOT, moby_flag);
    } else {
      return true;
    }
  }
}

async function SEARCH_LIST(obj, tbl, lvl, moby_flag = false) {
  let fls = 0, nobj = 0;
  if (obj = first(obj)) {
    for (;;) {
      if (!(lvl == P_SRCBOT) && getPropAddr(obj, P.SYNONYM) && (await THIS_IT$(obj))) {
        if ((loc(obj) == GLOBAL_OBJECTS) && (fls = getProp(obj, P.SCENARIO)) && !(fls == g.SCENARIO)) {
          fls = false;
        } else if ((loc(obj) == GLOBAL_OBJECTS) && (fls = getProp(obj, P.TRANSIENT)) && !(inTable(g.HERE, fls + 2, get(fls, 0)))) {
          fls = false;
        } else {
          await OBJ_FOUND(obj, tbl);
        }
      }
      if ((!(lvl == P_SRCTOP) || hasFlag(obj, SEARCHBIT) || hasFlag(obj, SURFACEBIT)) && (nobj = first(obj))) {
        if (hasFlag(obj, OPENBIT) || hasFlag(obj, TRANSBIT) || moby_flag) {
          fls = await SEARCH_LIST(obj, tbl, hasFlag(obj, SURFACEBIT) ? P_SRCALL : (hasFlag(obj, SEARCHBIT) ? P_SRCALL : P_SRCTOP), moby_flag);
        }
      }
      if (obj = next(obj)) {
      } else {
        return true;
      }
    }
  } else {
    return false;
  }
}

async function OBJ_FOUND(obj, tbl) {
  let ptr = 0;
  ptr = 1 + get(tbl, P_MATCHLEN);
  put(tbl, ptr, obj);
  return put(tbl, P_MATCHLEN, ptr);
}

async function TAKE_CHECK() {
  return (await ITAKE_CHECK(g.P_PRSO, getb(g.P_SYNTAX, P_SLOC1))) && (await ITAKE_CHECK(g.P_PRSI, getb(g.P_SYNTAX, P_SLOC2)));
}

async function ITAKE_CHECK(tbl, ibits) {
  let ptr = 0, obj = 0, taken = 0;
  if ((ptr = get(tbl, P_MATCHLEN)) && (btst(ibits, SHAVE) || btst(ibits, STAKE))) {
    for (;;) {
      if ((ptr = ptr - 1) < 0) {
        return true;
      } else {
        obj = get(tbl, ptr + 1);
        if (obj == IT) {
          if (!(await VISIBLE$(g.P_IT_OBJECT))) {
            await REFERRING();
            return false;
          } else {
            obj = g.P_IT_OBJECT;
          }
        } else if (obj == HIM) {
          if (!(await VISIBLE$(g.P_HIM_OBJECT))) {
            await REFERRING(true);
            return false;
          } else {
            obj = g.P_HIM_OBJECT;
          }
        } else if (obj == HER) {
          if (!(await VISIBLE$(g.P_HER_OBJECT))) {
            await REFERRING(true);
            return false;
          } else {
            obj = g.P_HER_OBJECT;
          }
        }
        if ((await HELD$(obj)) || (obj == HANDS || obj == INTNUM)) {
        } else {
          g.PRSO = obj;
          if (hasFlag(obj, TRYTAKEBIT)) {
            taken = true;
          } else if (!(g.WINNER == PROTAGONIST)) {
            taken = false;
          } else if (btst(ibits, STAKE) && eq(await ITAKE(false), true)) {
            taken = false;
          } else {
            taken = true;
          }
          if (taken && btst(ibits, SHAVE)) {
            if (1 < get(tbl, P_MATCHLEN)) {
              tell(S(YNH), " all those things!\n");
              return false;
            } else if (obj == NOT_HERE_OBJECT) {
              tell("[You can't see that here!]\n");
              return false;
            }
            if (g.WINNER == PROTAGONIST) {
              tell(S(YNH));
            } else {
              tell("It doesn't look as if");
              await TPRINT(g.WINNER);
              tell(" has");
            }
            await THIS_IS_IT(obj);
            await TRPRINT(obj);
            return false;
          } else if (!taken && (g.WINNER == PROTAGONIST)) {
            tell("[taking");
            await TPRINT(obj);
            tell(" first]\n");
          }
        }
      }
    }
  } else {
    return true;
  }
}

async function MANY_CHECK() {
  let loss = false, tmp = 0;
  if ((get(g.P_PRSO, P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC1), SMANY))) {
    loss = 1;
  } else if ((get(g.P_PRSI, P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC2), SMANY))) {
    loss = 2;
  }
  if (loss == 1) {
    tell("[One at a time, please!]\n");
    return false;
  } else if (loss) {
    tell("[Hey, you can't use more than one indirect object with \"");
    tmp = get(g.P_ITBL, P_VERBN);
    if (tmp == 0) {
      tell("tell");
    } else if (g.P_OFLAG || g.P_MERGED) {
      printB(get(tmp, 0));
    } else {
      await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    }
    tell("\".]\n");
    return false;
  } else {
    return true;
  }
}

async function THIS_IT$(obj) {
  let syns = 0, cnt = 0;
  if (hasFlag(obj, INVISIBLE)) {
    return false;
  } else if (!(syns = getPropAddr(obj, P.SYNONYM))) {
    return false;
  }
  if (g.P_NAM && !(inTable(g.P_NAM, syns, div(propSize(syns), 2)))) {
    return false;
  }
  if (g.P_ADJ) {
    if (!(syns = getPropAddr(obj, P.ADJECTIVE))) {
      return false;
    } else if (!(inTable(g.P_ADJ, syns, div(propSize(syns), 2)))) {
      return false;
    }
  }
  if (!(g.P_GWIMBIT == 0) && !(hasFlag(obj, g.P_GWIMBIT))) {
    return false;
  }
  return true;
}

