async function DESCRIBE_OBJECTS() {
  let o = 0, str = 0, av = loc(g.WINNER), tmp = 0;
  o = first(g.HERE);
  if (!o) {
    return false;
  }
  loop1: for (;;) {
    if (!o) {
      break loop1;
    } else if ((await DESCRIBABLE$(o)) && !(hasFlag(o, TOUCHBIT)) && (str = getProp(o, P.FDESC))) {
      await THIS_IS_IT(o);
      crlf();
      tell(S(str));
      if (hasFlag(o, CONTBIT)) {
        await DESCRIBE_CONTENTS(o, true, D_ALL$ + D_PARA$);
      }
      crlf();
    }
    o = next(o);
  }
  o = first(g.HERE);
  loop2: for (;;) {
    if (!o) {
      break loop2;
    } else if (!(await DESCRIBABLE$(o)) || (getProp(o, P.FDESC) && !(hasFlag(o, TOUCHBIT)))) {
    } else if ((str = getProp(o, P.DESCFCN)) && (tmp = await apply(str, M_OBJDESC$, o))) {
      if (!(tmp == M_FATAL)) {
        await THIS_IS_IT(o);
        crlf();
        if (str = await apply(str, M_OBJDESC, o)) {
          if (hasFlag(o, CONTBIT) && (str != M_FATAL)) {
            await DESCRIBE_CONTENTS(o, true, D_ALL$ + D_PARA$);
          }
        }
        crlf();
      }
    } else if (str = getProp(o, P.LDESC)) {
      await THIS_IS_IT(o);
      crlf();
      tell(S(str));
      if (hasFlag(o, CONTBIT)) {
        await DESCRIBE_CONTENTS(o, true, D_ALL$ + D_PARA$);
      }
      crlf();
    }
    o = next(o);
  }
  await DESCRIBE_CONTENTS(g.HERE, false, false);
  if (av && !(g.HERE == av)) {
    return await DESCRIBE_CONTENTS(av, false, false);
  } else {
    return false;
  }
}

async function DESCRIBE_CONTENTS(obj, level = (-1), all$ = D_ALL$) {
  let f = false, n_ = 0, _1st$ = true, it$ = false, two$ = false, start$ = false, para$ = false, db = 0;
  if (level == 2) {
    level = true;
    para$ = true;
    start$ = true;
  } else if (btst(all$, D_PARA$)) {
    para$ = true;
  }
  n_ = first(obj);
  if (start$ || (loc(obj) == ROOMS) || hasFlag(obj, PERSON) || (n_ && hasFlag(obj, CONTBIT) && (hasFlag(obj, OPENBIT) || hasFlag(obj, TRANSBIT)) && ((level == (-1)) || hasFlag(obj, SEARCHBIT)))) {
    loop1: for (;;) {
      if (!n_ || ((await DESCRIBABLE$(n_)) && (btst(all$, D_ALL$) || (await SIMPLE_DESC$(n_))))) {
        if (f) {
          if (_1st$) {
            _1st$ = false;
            if (level == false || level == true) {
              if (!start$) {
                if (!para$) {
                  para$ = true;
                  crlf();
                } else if (level == true) {
                  tell(" ");
                }
                await DESCRIBE_START(obj, n_);
              }
            } else if (!(level == (-1))) {
              tell(S(level));
            }
          } else if (n_) {
            tell(", ");
          } else {
            tell(" and ");
          }
          await PRINTA(f);
          if (!it$ && !two$) {
            it$ = f;
          } else {
            two$ = true;
            it$ = false;
          }
        }
        f = n_;
      }
      if (n_) {
        n_ = next(n_);
      }
      if (!f && !n_) {
        if (it$ && !two$) {
          await THIS_IS_IT(it$);
        }
        if (_1st$ && start$) {
          tell(" nothing");
          return false;
        } else if (!_1st$ && (level == false || level == true)) {
          if (obj == g.HERE) {
            tell(" here");
          }
          tell(".");
        }
        break loop1;
      }
    }
    if (level == false || level == true) {
      f = first(obj);
      loop2: for (;;) {
        if (!f) {
          break loop2;
        } else if (hasFlag(f, CONTBIT) && (await DESCRIBABLE$(f, true)) && (btst(all$, D_ALL$) || (await SIMPLE_DESC$(f)))) {
          db = g.D_BIT;
          g.D_BIT = false;
          if (await DESCRIBE_CONTENTS(f, true, para$ ? (D_ALL$ + D_PARA$) : D_ALL$)) {
            _1st$ = false;
            para$ = true;
          }
          g.D_BIT = db;
        }
        f = next(f);
      }
    }
    if (!_1st$ && (level == false || level == true) && (obj == g.HERE || obj == loc(g.WINNER))) {
      crlf();
    }
    return !_1st$;
  } else {
    return false;
  }
}

async function DESCRIBE_START(obj, n_) {
  if (obj == g.HERE) {
    tell("There is ");
    return true;
  } else if (obj == PROTAGONIST) {
    if (g.D_BIT == WORNBIT) {
      tell(" You are wearing ");
      return true;
    } else {
      tell("You are carrying ");
      return true;
    }
  } else if (hasFlag(obj, PERSON)) {
    await CTHE_PRINT(obj);
    tell(" wears ");
    return true;
  } else if (obj == BYSTANDER_CLOTHES) {
    tell("Pinned to ");
    await THE_PRINT(obj);
    tell(" is ");
    return true;
  } else if (hasFlag(obj, SURFACEBIT)) {
    tell("Sitting on ");
    await THE_PRINT(obj);
    tell(" is ");
    return true;
  } else {
    await CTHE_PRINT(obj);
    tell(" contains ");
    return true;
  }
}

async function DESCRIBABLE$(obj, cont$ = false) {
  if (hasFlag(obj, INVISIBLE)) {
    return false;
  } else if (obj == g.WINNER) {
    return false;
  } else if ((obj == loc(g.WINNER)) && !(g.HERE == loc(g.WINNER))) {
    return false;
  } else if (!cont$ && hasFlag(obj, NDESCBIT)) {
    return false;
  } else if (g.D_BIT) {
    if (g.D_BIT > 0) {
      if (hasFlag(obj, g.D_BIT)) {
        return true;
      } else {
        return false;
      }
    } else if (!(hasFlag(obj, -g.D_BIT))) {
      return true;
    } else {
      return false;
    }
  } else {
    return true;
  }
}

async function SIMPLE_DESC$(obj) {
  let str = 0;
  if (getProp(obj, P.FDESC) && !(hasFlag(obj, TOUCHBIT))) {
    return false;
  } else if ((str = getProp(obj, P.DESCFCN)) && (await apply(str, M_OBJDESC$, obj))) {
    return false;
  } else if (getProp(obj, P.LDESC)) {
    return false;
  } else {
    return true;
  }
}

