async function YES$(to_person = false) {
  restart: for (;;) {
    if (to_person) {
      print(">>");
    } else {
      print(">");
    }
    putb(g.P_INBUF, 1, 0);
    await read(g.P_INBUF, g.P_LEXV);
    if (await YES_WORD$(get(g.P_LEXV, 1))) {
      return true;
    } else if (eq(get(g.P_LEXV, 1), W.N, W.NO)) {
      return false;
    } else if (to_person == BAD_SPY) {
      tell("\"Please, just a simple yes or no.\"");
      crlf();
      crlf();
      continue restart;
    } else {
      tell("Please answer YES or NO.");
    }
    crlf();
    crlf();
    continue restart;
  }
}

async function YES_WORD$(wrd) {
  if (wrd == W.YES || wrd == W.Y) {
    return true;
  } else if (wrd == W.OK || wrd == W.OKAY) {
    return true;
  } else {
    return false;
  }
}

async function FINISH(contin = false) {
  let w_ = 0;
  restart: for (;;) {
    highlight(H_NORMAL);
    crlf();
    crlf();
    tell("Would you like to ");
    if (contin) {
      tell("continue with the next scenario, ");
    }
    tell("start over, restore a saved position, get a hint, or end this session of the game?\n(Type ");
    if (contin) {
      tell("CONTINUE, ");
    }
    tell("RESTART, RESTORE, HINT, or QUIT) >");
    putb(g.P_INBUF, 1, 0);
    await read(g.P_INBUF, g.P_LEXV);
    if (eq(w_ = get(g.P_LEXV, 1), W.RESTART)) {
      await restart();
      tell("Failed.\n");
      return await FINISH(contin);
    } else if (w_ == W.RESTORE) {
      if (await restore()) {
        return false;
      } else {
        tell("Failed.\n");
        return await FINISH(contin);
      }
    } else if (w_ == W.HINT) {
      await V_HINT();
      continue restart;
    } else if (w_ == W.QUIT || w_ == W.Q) {
      return await quit();
    } else if (contin && (w_ == W.CONTINUE || w_ == W.C)) {
      await FLUSH_BAD_SCENARIO(contin);
      if (contin == 2) {
        return await START_SCENARIO_2(true);
      } else {
        return await START_SCENARIO_3(true);
      }
    } else {
      continue restart;
    }
  }
}

