async function V_WALK() {
  let pt = 0, pts = 0, str = 0, obj = 0, rm = 0;
  restart: for (;;) {
    if (!g.P_WALK_DIR) {
      await PERFORM(V.WALK_TO, g.PRSO);
      return true;
    } else if (pt = getPropAddr(g.HERE, g.PRSO)) {
      if (eq(pts = propSize(pt), UEXIT)) {
        return await GOTO(get(pt, REXIT));
      } else if (pts == NEXIT) {
        tell(S(get(pt, NEXITSTR)), "\n");
        return M_FATAL;
      } else if (pts == FEXIT) {
        if (rm = await apply(get(pt, FEXITFCN))) {
          if ((g.SCENARIO == 3) && (await BACKTRACK$(rm, true))) {
            return M_FATAL;
          }
          return await GOTO(rm);
        } else {
          return M_FATAL;
        }
      } else if (pts == SEXIT) {
        if (str = get(pt, SEXITSTR)) {
          if ((g.SCENARIO == 3) && (await BACKTRACK$(get(pt, REXIT)))) {
            return M_FATAL;
          } else {
            tell(S(str), "\n");
          }
        }
        if (str = globalValue(getb(pt, SEXITFLG))) {
          crlf();
        }
        return await GOTO(get(pt, REXIT), str);
      } else if (pts == DEXIT) {
        if (hasFlag(obj = get(pt, DEXITOBJ), OPENBIT)) {
          return await GOTO(get(pt, REXIT));
        } else if (str = get(pt, DEXITSTR)) {
          tell(S(str), "\n");
          g.P_IT_OBJECT = obj;
          return M_FATAL;
        } else {
          tell("The ");
          await DPRINT(obj);
          tell(" is closed.\n");
          g.P_IT_OBJECT = obj;
          return M_FATAL;
        }
      } else {
        return false;
      }
    } else if ((g.PRSO == P.IN) && (str = getProp(g.HERE, P.IN_DIR))) {
      g.PRSO = str;
      continue restart;
    } else if ((g.PRSO == P.OUT) && (str = getProp(g.HERE, P.OUT_DIR))) {
      g.PRSO = str;
      continue restart;
    } else {
      if (g.PRSO == P.OUT || g.PRSO == P.IN) {
        await V_WALK_AROUND();
      } else {
        tell(S(CANT_GO));
      }
      return M_FATAL;
    }
  }
}

