async function V_HINT() {
  let curq = 0, curl = 0, chr = 0, maxq = 0, maxl = 0, q = false;
  restart: for (;;) {
    if (g.HINTS_OFF) {
      tell("[Hints have been disallowed for this session.]\n");
      return true;
    } else if (!g.HINT_WARNING) {
      g.HINT_WARNING = true;
      tell("[Warning: It is recognized that the temptation for help may at times be so exceedingly strong that you might fetch hints prematurely. Therefore, you may at any time during the story type HINTS OFF, and this will disallow the seeking out of help for the present session of the story. If you still want a hint now, indicate HINT.]\n");
      return true;
    }
    if (g.SCENARIO == 2) {
      g.HINT_TBL = g.HINT_TBL_2;
    } else if (g.SCENARIO == 1) {
      g.HINT_TBL = g.HINT_TBL_1;
    } else {
      g.HINT_TBL = g.HINT_TBL_3;
    }
    maxq = get(g.HINT_TBL, 0);
    await INIT_HINT_SCREEN();
    cursorSet(4, 1);
    maxl = await PUT_UP_QUESTIONS(1);
    curq = 1;
    curl = 5;
    if (g.LAST_HINT > 0) {
      curl = g.LAST_HINT;
    }
    if (g.LAST_Q > 0) {
      curq = g.LAST_Q;
    }
    cursorSet(curl, 2);
    print("->");
    loop1: for (;;) {
      chr = await readChar(1);
      if (chr == 81 || chr == 113) {
        g.LAST_HINT = curl;
        g.LAST_Q = curq;
        q = true;
        break loop1;
      } else if (chr == 78 || chr == 110) {
        if (curq == maxq) {
        } else {
          cursorSet(curl, 2);
          print("  ");
          curl = curl + 1;
          curq = curq + 1;
          cursorSet(curl, 2);
          print("->");
        }
      } else if (chr == 80 || chr == 112) {
        if (curq == 1) {
        } else {
          cursorSet(curl, 2);
          print("  ");
          curl = curl - 1;
          curq = curq - 1;
          cursorSet(curl, 2);
          print("->");
        }
      } else if (chr == 13 || chr == 10) {
        g.LAST_HINT = curl;
        g.LAST_Q = curq;
        await DISPLAY_HINT(curq);
        break loop1;
      }
    }
    if (!q) {
      continue restart;
    }
    splitWindow(0);
    clearScreen(-1);
    bufOut(true);
    await V_$ISL();
    tell("Back to the game...\n");
    return true;
  }
}

async function DISPLAY_HINT(n_) {
  let h = 0, mx = 0, cnt = HINT_HINTS, chr = 0, flg = true;
  splitWindow(0);
  clearScreen(-1);
  splitWindow(3);
  setWindow(S_WINDOW);
  cursorSet(1, 1);
  await INVERSE_LINE();
  (await CENTER_LINE(1, "INVISICLUES (TM)", 16));
  cursorSet(3, 1);
  await INVERSE_LINE();
  (await LEFT_LINE(3, " RETURN for hint"));
  (await RIGHT_LINE(3, "Q to go back", 12));
  highlight(H_BOLD);
  await CENTER_LINE(2, get(h = get(g.HINT_TBL, n_), HINT_QUESTION));
  highlight(H_NORMAL);
  mx = get(h, 0);
  setWindow(S_TEXT);
  bufOut(true);
  crlf();
  loop1: for (;;) {
    if (cnt == get(h, HINT_SEEN)) {
      break loop1;
    } else {
      tell(S(get(h, cnt)), "\n\n");
      cnt = cnt + 1;
    }
  }
  loop2: for (;;) {
    if (flg && (cnt > mx)) {
      flg = false;
      tell("[That's all folks!]\n");
    } else if (flg) {
      tell("Hint (");
      if ((mx - cnt) == 0) {
        tell("last");
      } else {
        tell(N(mx - cnt), " left");
      }
      tell(") -> ");
      flg = false;
    }
    chr = await readChar(1);
    if (chr == 81 || chr == 113) {
      put(h, HINT_SEEN, cnt);
      break loop2;
    } else if (chr == 13 || chr == 10) {
      if (cnt > mx) {
      } else {
        flg = true;
        tell(S(get(h, cnt)), "\n\n");
        cnt = cnt + 1;
        if (cnt > mx) {
          flg = false;
          tell("[That's all folks!]\n");
        }
      }
    }
  }
  bufOut(false);
  return true;
}

async function PUT_UP_QUESTIONS(st) {
  let mxq = 0, mxl = 0, ln = 0;
  mxq = get(g.HINT_TBL, 0);
  mxl = getb(0, 32);
  ln = 6;
  for (;;) {
    ln = ln + 1;
    if (st > mxq) {
      cursorSet(ln - 2, 1);
      tell("[Last question]");
      return mxq;
    } else {
      cursorSet(ln - 2, 1);
      tell("    ", S(get(get(g.HINT_TBL, st), HINT_QUESTION)));
    }
    st = st + 1;
  }
}

