async function CENTER_LINE(ln, str, len = 0, inv = true) {
  if (len == 0) {
    dirOut(D_TABLE_ON, g.DIROUT_TBL);
    tell(S(str));
    dirOut(D_TABLE_OFF);
    len = get(g.DIROUT_TBL, 0);
  }
  cursorSet(ln, div(getb(0, 33) - len, 2));
  if (inv) {
    highlight(H_INVERSE);
  }
  tell(S(str));
  if (inv) {
    return highlight(H_NORMAL);
  } else {
    return false;
  }
}

async function LEFT_LINE(ln, str, inv = true) {
  cursorSet(ln, 1);
  if (inv) {
    highlight(H_INVERSE);
  }
  tell(S(str));
  if (inv) {
    return highlight(H_NORMAL);
  } else {
    return false;
  }
}

async function RIGHT_LINE(ln, str, len = 0, inv = true) {
  if (len == 0) {
    dirOut(3, g.DIROUT_TBL);
    tell(S(str));
    dirOut(-3);
    len = get(g.DIROUT_TBL, 0);
  }
  cursorSet(ln, getb(0, 33) - len);
  if (inv) {
    highlight(H_INVERSE);
  }
  tell(S(str));
  if (inv) {
    return highlight(H_NORMAL);
  } else {
    return false;
  }
}

async function I_120_SECONDS() {
  if (!(loc(RIPPED_CLOTHES) == WOUNDED_LEFT_ARM)) {
    if ((g.HEALTH = g.HEALTH - 1) < 1) {
      return (await JIGS_UP("You pass out from loss of blood."));
    } else {
      highlight(H_BOLD);
      tell("\n", S(get(g.HEALTH_TBL, div(g.HEALTH, 2))));
      highlight(H_NORMAL);
      return crlf();
    }
  } else {
    return false;
  }
}

async function I_30_SECONDS() {
  let tmp = 0, hf = 0, oc = loc(CAR);
  g._30_TIMER = g._30_TIMER + 1;
  if (mod(g._30_TIMER, 4) == 0) {
    await I_120_SECONDS();
  }
  if ((g.WOOD_TIMER = g.WOOD_TIMER - 1) < 0) {
    return await RUN_WOOD_SEQUENCE();
  } else if (!(g.CAR_SEQUENCE == 0)) {
    return await RUN_CAR_SEQUENCE();
  } else if (g.CAR_ON_ROAD$) {
    tmp = get(g.RESTED_ROAD_TBL, 0);
    if (tmp == 0) {
      remove(CAR);
    } else {
      move(CAR, tmp);
    }
    g.RESTED_ROAD_TBL = g.RESTED_ROAD_TBL + 2;
    if (tmp == 0) {
      if (g.HERE == B8 || g.HERE == C8 || g.HERE == D8) {
        (await BOLDTELL("You watch as the automobile speeds into the tunnel and disappears."));
      }
      return g.CAR_ON_ROAD$ = false;
    } else if (g.HERE == tmp) {
      highlight(H_BOLD);
      crlf();
      await CAR_NEARLY_HITS();
      return true;
    } else if ((tmp == ROAD_END) && !g.SEQUENCE_RUN$) {
      g.SEQUENCE_RUN$ = true;
      g.CAR_SEQUENCE = 1;
      return await RUN_CAR_SEQUENCE();
    } else if (oc == ROOMS) {
      return true;
    } else if ((tmp == D6) && g.SEQUENCE_RUN$ && (g.HERE == NORTH_HUT || g.HERE == C5)) {
      return (await BOLDTELL("You watch as the car makes a three-point turn, then heads back down the road to the south."));
    } else {
      return await GONE_TO_THE_DOGS$(await HOW_FAR(oc, g.HERE, true), await HOW_FAR(tmp, g.HERE, true), CAR);
    }
  } else {
    return false;
  }
}

async function GONE_TO_THE_DOGS$(dl, ndl, bogey = DOGS, bmove = true) {
  let n_ = false, s_ = false, e = false, w_ = false, t1 = 0, t2 = 0, f = false;
  if (bmove) {
    highlight(H_BOLD);
  }
  if ((t1 = getProp(g.HERE, P.NS)) > (t2 = getProp(loc(bogey), P.NS))) {
    n_ = true;
  } else if (t1 < t2) {
    s_ = true;
  }
  if ((t1 = getProp(g.HERE, P.EW)) > (t2 = getProp(loc(bogey), P.EW))) {
    w_ = true;
  } else if (t1 < t2) {
    e = true;
  }
  if (dl > 3) {
    if (ndl < 4) {
      crlf();
      tell("You can hear ");
      await PRINTA(bogey);
      tell(" off to the ");
      setFlag(bogey, PENBIT);
      f = true;
    } else {
      if (bmove) {
        highlight(H_NORMAL);
      }
      return true;
    }
  } else if ((ndl < dl) || (ndl == 0)) {
    if (ndl == 2) {
      crlf();
      if (bogey == DOGS) {
        tell("The sound of barking dogs echoes into the night. They");
        if (hasFlag(bogey, PENBIT)) {
          if (!bmove) {
            tell(" are");
          } else {
            tell("'ve moved");
          }
          tell(" closer now, perhaps not");
        } else {
          setFlag(bogey, PENBIT);
          tell(" can't be");
        }
      } else if (hasFlag(g.HERE, ROADBIT)) {
        if (hasFlag(bogey, PENBIT)) {
          tell("The");
        } else {
          setFlag(bogey, PENBIT);
          tell("An");
        }
        tell(" automobile comes into view, moving slowly; it's no");
      } else if (!(hasFlag(bogey, PENBIT))) {
        setFlag(bogey, PENBIT);
        tell("You can hear an automobile engine close by; it can't be");
      } else {
        tell("The automobile's engine sounds closer now; it can't be");
      }
      tell(" more than a few hundred yards to the ");
      f = true;
    } else if (ndl == 1) {
      if (bogey == DOGS) {
        crlf();
        tell("The sound of the dogs is much louder now, and you can hear the shouting voices of the guards they accompany. They can't be more than a hundred yards to the ");
        f = true;
      } else if (hasFlag(g.HERE, ROADBIT)) {
        if (g.HERE == get(g.RESTED_ROAD_TBL, 0)) {
          tell("\nThe automobile is bearing down on you now, though it doesn't seem as if the driver has taken notice. He's no more than a hundred yards away.");
        } else {
          tell("\nThe automobile is only a hundred yards from you, but it is moving away. It will soon be out of sight.");
        }
      } else {
        tell("\nThe automobile is much closer now, perhaps no more than one hundred yards to the ");
        f = true;
      }
    } else {
      tell("\nThe sound of the dogs seems to come from all around you. They can't be more than fifty yards away.");
    }
  } else if (ndl == dl) {
    if (bogey == DOGS) {
      if (bmove && eq(getProp(t1 = loc(DOGS), P.EW), 4) && eq(getProp(t1, P.NS), 5)) {
        tell("\nThe dogs sound just a little bit closer and they still");
      } else if (bmove) {
        tell("\nThe dogs are no closer, but now they");
      } else {
        tell("You've moved such that the dogs now");
      }
      tell(" seem to be off to the ");
    } else {
      tell("\nFrom the sound of it, the car is now off to the ");
    }
    f = true;
  } else if (ndl > 3) {
    if (bmove) {
      crlf();
    }
    if (bogey == DOGS) {
      tell("To your relief, the sound of the dogs has faded into the distance.");
    } else {
      tell("The sounds of the automobile fade into the night air.");
    }
  } else {
    if (bogey == DOGS) {
      if (bmove) {
        tell("\nThe sounds of the dogs seem");
      } else {
        tell("You've moved such that the barking seems");
      }
      tell(" farther away and to the ");
    } else {
      tell("\nThe automobile sounds farther away and to the ");
    }
    f = true;
  }
  if (f) {
    if (n_) {
      tell("north");
    } else if (s_) {
      tell("south");
    }
    if (e) {
      tell("east");
    } else if (w_) {
      tell("west");
    }
    tell(".");
    if ((bogey == DOGS) && g.LOST_SCENT) {
      tell(" The dogs' barking is more shrill now than when you first heard it.");
    }
  }
  if (bmove) {
    highlight(H_NORMAL);
    crlf();
  } else {
    crlf();
    crlf();
  }
  return true;
}

async function GLOBAL_TOURNIQUET_F() {
  if (isVerb(V.MAKE) && g.PRSI && !g.CLOTHES_RIPPED) {
    if (g.PRSI == CLOTHES) {
      await PERFORM(V.RIP, CLOTHES);
      return true;
    } else {
      tell("You won't have any luck making a tourniquet out of that.\n");
      return true;
    }
  } else if (isVerb(V.MAKE)) {
    tell("That's easy enough to say; the question is really how you can make one.\n");
    return true;
  } else if (isVerb(V.FIND)) {
    tell("It's unlikely that you'll just run into one. You'd do better to make one.\n");
    return true;
  } else {
    return false;
  }
}

