async function TIMING_OBJECT_F() {
  let tmp = 0;
  if (isVerb(V.SET)) {
    tell("You can only do three things to the timer: reset it, turn it on, and turn it off.\n");
    return true;
  } else if (isVerb(V.ON)) {
    g.CHRONOGRAPH_ON = true;
    g.CLOCK_MOVE = 0;
    tell("The ");
    await DPRINT(g.PRSO);
    tell(" is on.\n");
    return true;
  } else if (isVerb(V.OFF)) {
    g.CHRONOGRAPH_ON = false;
    tell("The ");
    await DPRINT(g.PRSO);
    tell(" is off.\n");
    return true;
  } else if (isVerb(V.DROP)) {
    tell("Not a good idea; you'll probably need it.\n");
    return true;
  } else if (isVerb(V.RESET)) {
    g.CHRONOGRAPH_TIME = 0;
    tell("The ");
    await DPRINT(g.PRSO);
    tell(" is now reset.\n");
    g.CLOCK_MOVE = 0;
    await REDISPLAY_CHRONOGRAPH();
    return true;
  } else if (isVerb(V.READ)) {
    tell("The time appears on your status line.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("The watch is a precision Swiss instrument, incorporating both a digital clock and a one-hour timer.\n");
    return true;
  } else {
    return false;
  }
}

async function REDISPLAY_CHRONOGRAPH() {
  let tmp = 0;
  tmp = g.CHRONOGRAPH_ON;
  g.CHRONOGRAPH_ON = true;
  await UPDATE_CHRONOGRAPH(0, true);
  return g.CHRONOGRAPH_ON = tmp;
}

async function SEARCHLIGHTS_F() {
  if (isVerb(V.EXAMINE, V.EXAMINE_THROUGH)) {
    tell("The three searchlights are rotating clockwise. The first and third are moving at the same slow pace, and the middle one is moving quite a bit faster. At this moment, the ");
    await SL_TELL(false);
    if (!g.SL_WATCH) {
      tell(" Since the lights are always in motion, it might be best to WATCH them.");
    }
    crlf();
    return true;
  } else if (isVerb(V.WATCH)) {
    g.CHRONOGRAPH_ON = true;
    if (g.SL_WATCH) {
      tell("You already are.\n");
      return true;
    }
    if (g.G_WATCH) {
      await PERFORM(V.OFF_2, TIMING_OBJECT, GUARDS);
    }
    g.SL_WATCH = true;
    g.CLOCK_MOVE = 4;
    await SCREEN_1();
    cursorSet(2, 2);
    tell("Left:");
    cursorSet(2, div(getb(0, 33), 2) - 6);
    tell("Center:");
    cursorSet(2, getb(0, 33) - 11);
    tell("Right:");
    await SL_WATCHER();
    await SCREEN_0();
    crlf();
    await PERFORM(V.EXAMINE, SEARCHLIGHTS);
    tell("\nNow that you're watching the searchlights, you'll take a moment to check on them after everything you do until you stop watching them, or move out of range.\n");
    return true;
  } else if (isVerb(V.OFF_2) && (g.PRSO == TIMING_OBJECT || g.PRSO == WATCHING_OBJECT)) {
    if (!g.SL_WATCH) {
      tell("You weren't watching them.\n");
      return true;
    }
    g.SL_WATCH = false;
    g.CLOCK_MOVE = 4;
    await FLUSH_WATCHER();
    if (!g.SAVE_FLAG) {
      tell("You're no longer watching the searchlights.\n");
    }
    return true;
  } else {
    return false;
  }
}

