async function HUT_BACK_DOOR_F() {
  if (g.HUT_BURNING) {
    tell("The door is completely in flames.\n");
    return true;
  } else if (isVerb(V.KNOCK)) {
    tell("What, are you crazy? What if someone's home?\n");
    return true;
  } else if (isVerb(V.OPEN) && !(hasFlag(g.PRSO, OPENBIT)) && !g.DOOR_OILED) {
    tell("The door squeaks loudly as you open it.\n");
    if (eq(loc(HUT_MAN), HUT_LIVING, HUT_BEDROOM)) {
      crlf();
      (await JIGS_UP("Unfortunately, someone was indeed home, and carrying a weapon at that. He motions you to the door, and you follow him as he telephones for the border police."));
    }
    return setFlag(g.PRSO, OPENBIT);
  } else if ((isVerb(V.OIL) && (loc(OIL_CAN) == g.WINNER)) || (isVerb(V.PUT) && (g.PRSO == OIL_CAN))) {
    if (g.HERE == BEHIND_HUT) {
      tell("A good idea, but the hinges are on the inside, so you'll have to do it from there.\n");
      return true;
    } else {
      tell("The squeaky door gets the grease, or words to that effect. The door seems quieter already.\n");
      return g.DOOR_OILED = true;
    }
  } else if (isVerb(V.OIL)) {
    tell("You aren't holding any oil.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("The wooden door is chipped in places, but is otherwise in pretty good shape. The hinges, though, are rusted badly");
    if (!g.DOOR_OILED) {
      tell(" - it'll make some noise when it's opened");
    }
    tell(S(g.PERIOD_CR));
    return true;
  } else if (isVerb(V.CLOSE) && !g.DOOR_OILED && hasFlag(g.PRSO, OPENBIT)) {
    tell("The door squeaks loudly as you start to pull it closed.\n");
    return clearFlag(g.PRSO, OPENBIT);
  } else {
    return false;
  }
}

async function MAN_AT_HOME$() {
  let $1;
  if ($1 = eq(loc(HUT_MAN), HUT_STORAGE, HUT_LIVING, HUT_BEDROOM)) {
    return $1;
  } else {
    return false;
  }
}

