async function PLATFORM_MOVE(rm) {
  tell("You walk slowly through the crowd");
  if (!(loc(g.CONTACT) == g.HERE)) {
    tell(", eyes open but totally in the dark regarding the nature of your contact");
  }
  tell(".");
  if ((g.SUSPICION > 0) && !g.FOLLOW_WARNING) {
    g.FOLLOW_WARNING = true;
    tell(" It's probably nothing, but you could swear that a man you see behind you was also behind you before you started walking.");
  } else if (g.FOLLOW_WARNING && !g.FOLLOW_SURE) {
    if (prob(40)) {
      g.FOLLOW_SURE = true;
      tell(" There he is again, ducking behind a group of tourists. It's all but certain you're being followed!");
    } else {
      tell(" You nonchalantly look around, and are relieved that the man you saw earlier is no longer around.");
    }
  }
  if (rm == PLATFORM_1) {
    tell("\n\nYou've come to the northern end of the platform now, and you can see in the distance the darkness that is Litzenburg.");
  } else if (rm == PLATFORM_4) {
    tell("\n\nYou've arrived at the platform's southern end, and can look back into Frobnia, sighting its formidible border defenses: guard towers, searchlights, patrols, guard dogs - God knows what else. It's a whole lot better to have a ticket, and you smile, realizing that it's not easy this way either.");
  }
  crlf();
  g.DONT_DESCRIBE_ROOM = true;
  return rm;
}

async function PLATFORM_ROOM_F(rarg) {
  if (rarg == M_LOOK) {
    tell("The platform itself is the same size as the trains which cross the border here - four train-lengths - a hundred yards or so. The train you arrived on is standing here, each entrance door guarded so as to prevent passengers from reboarding until the train is ready to leave. Why? Don't ask.\n");
    tell("\nThere are people everywhere, milling back and forth - men, women, even a few children. And then there are the guards, the ones you can see, and, more troublesome, the ones you can't.\n\n");
    if (g.HERE == PLATFORM_1) {
      tell("Right now, you're standing at the northern end of the platform. Looking ahead, you can see the darkness that is Litzenburg at night. In just a few minutes, you hope to be there ... after making your contact.\n");
      return true;
    } else if (g.HERE == PLATFORM_2) {
      tell("You're now alongside the second car.\n");
      return true;
    } else if (g.HERE == PLATFORM_3) {
      tell("You're now alongside the third car.\n");
      return true;
    } else {
      tell("You're at the southern end of the platform. Looking back into Frobnia, you can start to make out the border defenses of Frobnia. Incredible. Guard towers. Searchlights. Patrols. Guard dogs. God knows what else. Better to have a ticket. You smile, thinking that even then it's not all that easy!\n");
      return true;
    }
  } else {
    return false;
  }
}

