async function PASS_MOVE(whr, nfp = false) {
  let bsl = 0;
  bsl = loc(BAD_SPY);
  if (!nfp) {
    tell("You move along the passageway until you come to ");
    if (whr == PASS_5) {
      tell("your own compartment");
    } else {
      tell("the ", S(get(g.PASS_TELLS, getProp(whr, P.NS))));
    }
    tell(".");
  }
  if (g.AT_STATION) {
    tell(" Just north of your position, a guard is standing. He is motioning you out of the train to the south.");
  }
  if (!g.GUARD_NOTICE_FLAG) {
    tell(" You scan the passageway, noting guards at either end, machine guns poised at their sides. You don't remember them from the beginning of the trip, so you can only suppose that security has been tightened in the search for the American agent.");
    g.GUARD_NOTICE_FLAG = true;
  }
  if (bsl && hasFlag(bsl, HUTBIT)) {
    tell("\n\n");
    if (g.BAD_SPY_SEEN) {
      tell("The man in the coat");
    } else {
      tell("Another man, wearing a trench coat,");
    }
    tell(" is ");
    if (g.BAD_SPY_SEEN == bsl) {
      tell("still ");
    }
    g.BAD_SPY_SEEN = bsl;
    if (bsl == whr) {
      tell("standing here");
    } else if (bsl == PASS_5) {
      tell("standing outside of your compartment, motioning for you to return");
    } else {
      tell("standing outside ");
      tell("the ", S(get(g.PASS_TELLS, getProp(bsl, P.NS))));
      tell(", and talking to its occupants in rapid-fire Frobnian");
    }
    await HST_CHECK(bsl, whr);
    tell(".");
  }
  await DOC_CHECK();
  crlf();
  g.DONT_DESCRIBE_ROOM = true;
  return whr;
}

async function DOC_CHECK() {
  if ((loc(BAD_SPY) == g.HERE) && (loc(DOCUMENT) == g.WINNER)) {
    tell("\n\n");
    remove(DOCUMENT);
    setFlag(DOCUMENT, PENBIT);
    tell("He looks again, this time directly at the document. \"Ah, thank you very much for returning this document,\" he says. He takes it from you and regards you with contempt. \"We may need to talk more about this later.\" And with this, he returns to his conversation with the other passengers.");
    return g.SUSPICION = g.SUSPICION + 1;
  } else {
    return false;
  }
}

async function HST_CHECK(bsl, whr, str = false) {
  if (!str) {
    (str = ". He gives you a sidelong glance, and then a subtle double take, and you fear you have given yourself away");
  }
  if ((await HST$()) && !g.HST_FLAG && ((await ABS(getProp(bsl, P.NS) - getProp(whr, P.NS))) < 3)) {
    tell(S(str));
    g.HST_FLAG = true;
    return g.SUSPICION = g.SUSPICION + 1;
  } else {
    return false;
  }
}

