async function DOWN_THE_DRAIN(obj, size = 2) {
  let off = 0, f = 0, n_ = 0;
  f = first(obj);
  loop1: for (;;) {
    if (!f) {
      break loop1;
    } else {
      n_ = next(f);
      if ((getProp(f, P.SIZE) < size) && !(f == TICKET || f == PASSPORT)) {
        remove(f);
        off = off + 1;
        put(g.DRAIN_TBL, off, f);
      }
    }
    f = n_;
  }
  if (!(off == 0)) {
    tell(" Down the drain, along with the water, goes the ");
    loop2: for (;;) {
      await DPRINT(get(g.DRAIN_TBL, off));
      if ((off = off - 1) < 1) {
        break loop2;
      } else if (off == 1) {
        tell(", and ");
      } else {
        tell(", ");
      }
    }
    tell(".");
    return true;
  } else {
    return false;
  }
}

