async function CAMERA_F() {
  let film = 0, shot = 0;
  film = first(CAMERA);
  if (isVerb(V.EXAMINE)) {
    tell("It's a Pentax 35-mm SLR camera; you could have done better, but the dollar's not been so good, and getting Japanese goods here is difficult at best. Right now, it's ");
    if (film == 0) {
      tell("not loaded with any film");
    } else if (!(hasFlag(film, FILMBIT))) {
      tell("got a ");
      await DPRINT(film);
      tell(" inside");
    } else if ((shot = getProp(film, P.SHOT)) == 0) {
      tell("got a ");
      await DPRINT(film);
      tell(" inside that's ready to be loaded");
    } else if (shot < 0) {
      tell("got a rewound ");
      await DPRINT(film);
      tell(" inside");
    } else {
      tell("loaded with a ");
      await DPRINT(film);
    }
    tell(". ");
    if (hasFlag(CAMERA, OPENBIT)) {
      tell("The back of the camera is open.");
    } else if (film && hasFlag(film, FILMBIT) && eq(getProp(film, P.SHOT), -1)) {
      tell("The gizmo on top says that the film inside is rewound.");
    } else if (film && hasFlag(film, FILMBIT)) {
      tell("According to the gizmo on top, you're currently at picture number ");
      tell(N(getProp(film, P.SHOT)));
      tell(" of a roll of 24.");
    }
    return crlf();
  } else if (isVerb(V.PUT) && (g.PRSI == CAMERA)) {
    if (!(hasFlag(CAMERA, OPENBIT))) {
      tell("The camera's not open.\n");
      return true;
    } else if (film) {
      tell("There's already something there.\n");
      return true;
    } else if (getProp(g.PRSO, P.SIZE) > 5) {
      tell("That won't fit in the camera.\n");
      return true;
    } else {
      tell("The ");
      await DPRINT(g.PRSO);
      tell(" is now resting in the camera.\n");
      return move(g.PRSO, g.PRSI);
    }
  } else if (isVerb(V.OPEN)) {
    if (hasFlag(CAMERA, OPENBIT)) {
      return await TOO_LATE();
    } else {
      setFlag(CAMERA, OPENBIT);
      tell("The camera is now opened.");
      if (film && hasFlag(film, FILMBIT) && !(eq(getProp(film, P.SHOT), -1, 0))) {
        if (film == COLOR_ROLL) {
          g.FILM_RUINED = true;
        }
        putProp(film, P.SHOT, -1);
        tell(" Sadly, the film was not rewound, so some of your photos have probably been destroyed. It's too late now, but you rewind the roll anyway.");
      }
      return crlf();
    }
  } else if (isVerb(V.CLOSE)) {
    if (hasFlag(CAMERA, OPENBIT)) {
      clearFlag(CAMERA, OPENBIT);
      tell("The camera is now closed.\n");
      return true;
    } else {
      return await TOO_LATE();
    }
  } else if (isVerb(V.LOAD)) {
    if (!film) {
      if (g.PRSI && hasFlag(g.PRSI, FILMBIT)) {
        await PERFORM(V.PUT, g.PRSI, g.PRSO);
        if (!(film = first(CAMERA)) || !(film == g.PRSI)) {
          return true;
        }
      } else {
        tell("In order to properly load the film into the camera's winding mechanism, you must first put the film in the camera.\n");
        return true;
      }
    }
    if (!(hasFlag(film, FILMBIT))) {
      tell("Not likely, with the ");
      await DPRINT(film);
      tell(" sitting in there.\n");
      return true;
    } else if (g.PRSI && !(film == g.PRSI)) {
      tell("There's another roll already in there.\n");
      return true;
    } else if ((shot = getProp(film, P.SHOT)) < 0) {
      tell("The film has been rewound back into the spool; there's no way to load it onto the winding mechanism now.\n");
      return true;
    } else if (film > 0) {
      tell("It's already loaded properly.\n");
      return true;
    } else {
      return true;
    }
  } else if (isVerb(V.REWIND)) {
    if (!film || !(hasFlag(film, FILMBIT))) {
      tell("There's no film in the camera.\n");
      return true;
    } else if (!((film = getProp(film, P.SHOT)) > 1)) {
      tell("The film in the camera isn't loaded.\n");
      return true;
    } else {
      putProp(first(CAMERA), P.SHOT, -1);
      tell("The film in the camera is now rewound.\n");
      return true;
    }
  } else {
    return false;
  }
}

