async function TAKE_A_PICTURE() {
  let film = 0, shot = 0;
  if (hasFlag(CAMERA, OPENBIT)) {
    tell("But the back of the camera is open!\n");
    return true;
  } else if (!(film = first(CAMERA))) {
    tell("There's no film in the camera, or hadn't you noticed?\n");
    return true;
  } else if (!(hasFlag(film, FILMBIT))) {
    tell("There's something in the camera, but it sure isn't film.\n");
    return true;
  } else if (eq(shot = getProp(film, P.SHOT), -1)) {
    tell("The camera's shutter makes a clicking noise, but nothing else happens; the film is rewound.\n");
    return true;
  } else if (shot == 0) {
    tell("The film's in the camera, all right, but it's not loaded.\n");
    return true;
  } else if (shot == 25) {
    tell("Nothing happens; it appears you've taken your last shot on this roll.\n");
    return true;
  } else {
    putProp(film, P.SHOT, shot = shot + 1);
    put(getProp(film, P.PHOTO), shot - 24, g.PRSO);
    tell("You take the picture of ");
    await THE_PRINT_PRSO();
    tell(". The film is automatically advanced to frame number ", N(shot), S(g.PERIOD_CR));
    return true;
  }
}

async function BYSTANDER_CLOTHES_F() {
  if (isVerb(V.TAKE_OFF, V.REMOVE)) {
    tell("This would be highly inappropriate.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    if (g.SCENARIO == 1) {
      tell("You are looking rather dapper in your business suit.");
    } else {
      tell("You're doing your best to look nondescript in your trench coat.\n");
    }
    if ((loc(CARNATION) == g.PRSO) && (g.SCENARIO == 1)) {
      tell(" A white carnation adorns your jacket's lapel.");
    }
    return crlf();
  } else if (isVerb(V.LOOK_INSIDE)) {
    tell("There's nothing in your clothes that can help you.\n");
    return true;
  } else if (isVerb(V.RIP)) {
    tell("Why on earth should you damage your rather expensive outfit?\n");
    return true;
  } else {
    return false;
  }
}

async function CARNATION_F() {
  if (isVerb(V.EXAMINE)) {
    tell("It's a sad looking carnation, though it is arguably in better shape than its previous owner.\n");
    return true;
  } else if (isVerb(V.TAKE_OFF) && (loc(g.PRSO) == BYSTANDER_CLOTHES)) {
    move(g.PRSO, g.WINNER);
    clearFlag(g.PRSO, WORNBIT);
    tell("You take off the carnation. It is a sorry sight.\n");
    return true;
  } else if (isVerb(V.WEAR) && !(hasFlag(g.PRSO, WORNBIT))) {
    move(g.PRSO, BYSTANDER_CLOTHES);
    setFlag(g.PRSO, WORNBIT);
    tell("You put the rumpled carnation through the hole in your lapel. Except for the contact, you can only pray that nobody notices.\n");
    return true;
  } else {
    return false;
  }
}

async function BAD_SPY_F() {
  if (isVerb(V.EXAMINE)) {
    tell("He is a rather large man, though unassuming in appearance. He wears an off-white trench coat and a hat and talks with a beautiful, resonant voice. In all, he doesn't appear very formidable, but your intuition tells you that he is a very high-level official - in what agency, you could never know.\n");
    return true;
  } else if (isVerb(V.BRIBE)) {
    tell("It's too risky; you'd probably end up in jail.\n");
    return true;
  } else if (isVerb(V.GIVE, V.SHOW) && (g.PRSO == SHRED || g.PRSO == SHREDS || g.PRSO == DOCUMENT)) {
    tell("Even in a text-only game, that would be stupid beyond words.\n");
    return true;
  } else if (isVerb(V.GIVE) && (g.PRSI == BAD_SPY)) {
    tell("He waves you away with his hand.\n");
    return true;
  } else if (isVerb(V.PHOTOGRAPH)) {
    tell("Seeing what you are about to do, he turns to you, and speaks harshly. \"This is not permitted.\" You decide against taking the picture.\n");
    return g.SUSPICION = g.SUSPICION + 1;
  } else if (isVerb(V.LISTEN)) {
    tell("You know little Frobnian, and he is speaking very quickly.\n");
    return true;
  } else {
    return false;
  }
}

async function I_BAD_SPY() {
  let sm = 0;
  let $1;
  g.BAD_SPY_COUNT = g.BAD_SPY_COUNT + 1;
  if ((mod(g.BAD_SPY_COUNT, 6) == 0) && ((sm = div(g.BAD_SPY_COUNT, 6)) < 7)) {
    move(BAD_SPY, sm = get(g.BAD_SPY_MOVES, sm));
    if (hasFlag(g.HERE, HUTBIT)) {
      highlight(H_BOLD);
      crlf();
      if (sm == PASS_1) {
        g.BAD_SPY_SEEN = true;
        tell("You watch as a man in a trench coat enters your car to the north. He ");
        if (!(hasFlag(COMP_N_DOOR, OPENBIT))) {
          tell("opens the door to the first compartment, and ");
        }
        tell("begins to speak to the occupants, though you can't make out a word.");
      } else if (sm == PASS_5 || sm == PASS_6) {
        if (sm == PASS_5) {
          tell("The man arrives at your compartment and sees that nobody is inside. After a moment, he looks in your direction");
        } else {
          tell("The man walks up to you,");
        }
        tell(" and speaks to you in a beautifully deep voice with a heavily Russian accent. \"Please return now to your compartment.\"");
        g.BAD_DISTANCE = await ABS(getProp(loc(BAD_SPY), P.NS) - getProp(g.HERE, P.NS));
        await SLOW_CLOCK_QUEUE(I_BAD_WAITS.id, 20);
      } else if (g.HERE == sm) {
        tell("The man politely thanks the people in the next compartment, closes their door, and moves to where you are standing. He looks you over briefly, then proceeds to speak to the occupants in what you realize to be Frobnian; sadly, you don't understand enough to make sense of his speech.");
      } else {
        tell("The man in the trench coat tips his hat at the occupants of the compartment, shuts the door, and moves to the next compartment, where he opens the door and starts to converse. He's now ");
        $1 = get(g.SMALL_NUMS_TBL, await ABS(getProp(sm, P.NS) - getProp(g.HERE, P.NS)));
        tell(S($1));
        tell(" away from you.");
      }
      (await HST_CHECK(sm, g.HERE, "\n\nThe man, seeming to notice you for the first time, turns casually in your direction. A second later, he seems to do a double take and you fear you have given yourself away."));
      await DOC_CHECK();
      highlight(H_NORMAL);
      return crlf();
    } else if ((sm == PASS_6) && (g.HERE == LAVATORY)) {
      await SLOW_CLOCK_QUEUE(I_BAD_LAV_WAITS.id, 20);
      return (await BOLDTELL("There are two sharp raps on the lavatory door, and a man with a thick accent speaks. \"Please forgive the intrusion, but I must have a word with you, outside, in your compartment.\""));
    } else if ((sm == PASS_5 || sm == PASS_6) && (g.HERE == COMP_5)) {
      await DE_SLOW_CLOCK_QUEUE();
      (await BOLDTELL("There are two sharp raps on your door, and a man wearing a trench coat enters."));
      await BAD_INTERVIEW();
      if (!g.PRSA) {
        g.READ_INTERRUPTED = true;
      }
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function BAD_INTERVIEW(force$ = false) {
  await DE_SLOW_CLOCK_QUEUE();
  g.BAD_INTERVIEW_FLAG = true;
  tell("\nHe speaks beautiful, correct English, though his accent is rather thick. \"I am so sorry to ");
  if (force$) {
    tell("well, shall I say 'insist'");
  } else {
    tell("intrude");
  }
  tell(", but I was hoping you could be of some assistance.\" His eyes dart around the room as he speaks, taking in everything. Then, his gaze settles on you - his searching eyes take you in from top to bottom");
  if (hasFlag(CARNATION, WORNBIT)) {
    setFlag(CARNATION, HUTBIT);
    g.SUSPICION = g.SUSPICION + 1;
    tell(", and you imagine that he is frowning slightly, as if slightly confused.");
  } else {
    tell(".");
  }
  if (loc(CAMERA) == g.WINNER) {
    tell(" He looks at the camera, and raises an eyebrow. \"You are taking pictures? I hope you are using fast film.\"");
    g.SUSPICION = g.SUSPICION + 1;
  }
  if (loc(STAINED_PAPER_TOWEL) == g.WINNER) {
    g.SUSPICION = g.SUSPICION + 1;
    tell(" He then stares for a moment at the blood-stained towel in your hand, then smiles and looks you in the eye.");
  }
  crlf();
  if ((await BAD_SEARCH(g.WINNER)) || (await BAD_SEARCH(g.HERE)) || (await BAD_SEARCH(COMP_SEAT_FRONT)) || (await BAD_SEARCH(COMP_SEAT_BACK))) {
    return true;
  }
  tell("\nHe casually takes a cigarette and a book of matches from his pocket and attempts to light a match, giving up after the fourth try. He smiles good-naturedly, and says, \"I should be giving these up anyway.\" He returns them to his pocket and continues.");
  tell("\n\n\"I will come to the point. We are looking for ");
  if (hasFlag(DOCUMENT, PENBIT)) {
    tell("the man who gave you the document. Perhaps you have seen where he has gone?\" He eyes you suspiciously, but you are relieved to be able to answer him honestly - you have no idea where he's gone.");
  } else {
    tell("a man - tall, slight, a bit disheveled - hurt, perhaps. We believe he may have come this way, and we have need to find him, for his own safety.\" He smiles wanly. \"Have you seen such a man?\"");
  }
  tell("\n\n");
  if (hasFlag(DOCUMENT, PENBIT)) {
  } else if (await YES$(BAD_SPY)) {
    crlf();
    if ((loc(COMP_BLOOD_STAIN) == g.HERE) || (loc(STAINED_PAPER_TOWEL) == g.WINNER)) {
      tell(S(g.BAD_YES_START), "\n\n");
      g.SUSPICION = g.SUSPICION + 1;
    } else {
      tell(S(g.BAD_YES_START));
      tell(" The man pauses for a moment, then looks around furtively, but unmistakably, as if he had misplaced something.\n\n");
      g.SUSPICION = g.SUSPICION + 2;
    }
  } else if ((loc(COMP_BLOOD_STAIN) == g.HERE) || (loc(STAINED_PAPER_TOWEL) == g.WINNER)) {
    crlf();
    tell("You answer negatively with a shake of your head and a curt \"Nobody like that has been here. Sorry.\"\n\n");
    tell("He ");
    if (loc(COMP_BLOOD_STAIN) == g.HERE) {
      tell("lowers his eyes to the floor, as if in thought");
    } else {
      tell("looks at your hands");
    }
    tell(", then looks you straight in the eye. \"You are certain, then?\" he asks, with a hint of humor - or is it disbelief? You again reassure him that you would certainly have noticed someone of that description.\n\n");
    g.SUSPICION = g.SUSPICION + 3;
  } else {
    crlf();
    tell("He looks around again briefly, and nods his head a few times as if agreeing with you.\n\n");
  }
  if (g.SUSPICION > 2) {
    tell("\"Well, thank you anyway. We shall be arriving at the checkpoint in a few minutes, and then we must conduct our border search - you understand. Until then, I would appreciate it if you would remain here.\" He leaves with a tip of his hat. As he leaves, he speaks briefly with one of the guards stationed in the passageway.\n");
    g.BAD_CONFINED = true;
  } else {
    clearFlag(COMP_5_DOOR, OPENBIT);
    tell("\"Thank you anyway. We shall be arriving shortly at the border, and I will see you again at that time.\" He leaves with a tip of his hat, closing the door behind him.\n");
  }
  g.I_FATAL = true;
  g.BAD_INTERVIEW_FLAG = false;
  return remove(BAD_SPY);
}

async function COMP_BLOOD_STAIN_F() {
  if ((isVerb(V.CLEAN) && (g.PRSI == WET_PAPER_TOWEL)) || (isVerb(V.CLEAN) && !g.PRSI && (loc(WET_PAPER_TOWEL) == g.WINNER))) {
    tell("You wipe up the drops of blood; it is unlikely anyone would notice the slight discoloration that remains.\n");
    move(STAINED_PAPER_TOWEL, g.WINNER);
    remove(WET_PAPER_TOWEL);
    return remove(COMP_BLOOD_STAIN);
  } else if ((isVerb(V.CLEAN) && (g.PRSI == PAPER_TOWEL)) || (isVerb(V.CLEAN) && !g.PRSI && (loc(PAPER_TOWEL) == g.WINNER))) {
    setFlag(g.PRSO, CROSSBIT);
    tell("The dry towel merely smears the blood around, leaving, in all, a bigger mess than when you started.\n");
    return true;
  } else if (isVerb(V.CLEAN)) {
    tell("It's a good idea to cover the agent's tracks, but you don't have anything suitable for cleaning up the mess.\n");
    return true;
  } else if (isVerb(V.PUT, V.PUT_ON) && (g.PRSI == COMP_BLOOD_STAIN)) {
    tell("You'd only ruin the ");
    await DPRINT(g.PRSO);
    tell(S(g.PERIOD_CR));
    return true;
  } else {
    return false;
  }
}

async function I_BAD_WAITS() {
  if (!(loc(BAD_SPY))) {
    return true;
  } else if (!((await ABS(getProp(loc(BAD_SPY), P.NS) - getProp(g.HERE, P.NS))) < g.BAD_DISTANCE) && !(g.HERE == COMP_5)) {
    if ((g.HERE == LAVATORY) || ((g.BAD_WAIT_COUNT = g.BAD_WAIT_COUNT + 1) > 4)) {
      highlight(H_BOLD);
      crlf();
      g.SUSPICION = g.SUSPICION + 1;
      if (g.HERE == LAVATORY) {
        tell("A guard forces his way into the lavatory and leads");
      } else {
        tell("The man signals to a guard, who arrives and forcibly takes");
      }
      tell(" you to your compartment. \"That is better,\" the trench coated man says.");
      highlight(H_NORMAL);
      crlf();
      await GOTO(COMP_5, false);
      await DE_SLOW_CLOCK_QUEUE();
      await BAD_INTERVIEW(true);
      return true;
    } else if (!(g.BAD_WAIT_COUNT == 1)) {
      return await BOLDTELL(get(g.BAD_WAIT_TBL, g.BAD_WAIT_COUNT));
    } else {
      return false;
    }
  } else if ((g.BAD_DISTANCE = g.BAD_DISTANCE - 1) < 1) {
    (await BOLDTELL("\"Thank you so much for your patience.\" He leads you into your compartment and shuts the door."));
    await GOTO(COMP_5, false);
    await BAD_INTERVIEW();
    await DE_SLOW_CLOCK_QUEUE();
    return true;
  } else {
    return false;
  }
}

async function I_BAD_LAV_WAITS() {
  if (!(loc(BAD_SPY))) {
    return true;
  } else if (hasFlag(LAVATORY_DOOR, OPENBIT)) {
    (await BOLDTELL("The man in the trench coat takes you by the arm and walks you back to your compartment."));
    await GOTO(COMP_5, false);
    await BAD_INTERVIEW();
    await DE_SLOW_CLOCK_QUEUE();
    return true;
  } else if ((g.BAD_WAIT_COUNT = g.BAD_WAIT_COUNT + 1) > 4) {
    (await BOLDTELL("Without warning, the door is knocked open by one of the uniformed guards. The man in the trench coat then takes you by the arm and escorts you back to your compartment."));
    g.SUSPICION = g.SUSPICION + 1;
    await GOTO(COMP_5, false);
    await BAD_INTERVIEW(true);
    await DE_SLOW_CLOCK_QUEUE();
    return true;
  } else if (!(g.BAD_WAIT_COUNT == 1)) {
    return await BOLDTELL(get(g.BAD_LAV_WAIT_TBL, g.BAD_WAIT_COUNT));
  } else {
    return false;
  }
}

async function GRAFFITI_F() {
  if (isVerb(V.READ, V.EXAMINE)) {
    tell("The words don't make a lot of sense, and your Frobnian is poor, but it seems to say:\n\n         BORDER ZONE\n    Written by Marc Blank\nCopyright (c) 1987, Infocom, Inc.\n\n");
    return true;
  } else {
    return false;
  }
}

async function TOWEL_DISPENSER_F() {
  if (isVerb(V.EXAMINE)) {
    tell("It's your ordinary metal towel dispenser. Here, as in the States, people tend to write grafitti on towel dispensers, and this one is no exception.");
    if (loc(PAPER_TOWEL) == g.PRSO) {
      tell(" You are in luck - there's at least one paper towel inside.");
    } else {
      tell(" It seems to be empty, which is somehow not surprising.");
    }
    return crlf();
  } else if (isVerb(V.OPEN)) {
    tell("You can't open it, reminding yourself of how stupid it is that all towel dispensers seem to be locked.\n");
    return true;
  } else if (isVerb(V.CLOSE)) {
    tell("It already is.\n");
    return true;
  } else if (isVerb(V.PUT) && (g.PRSI == TOWEL_DISPENSER)) {
    if (g.PRSO == DOCUMENT || g.PRSO == SHRED || g.PRSO == SHREDS) {
      move(g.PRSO, g.PRSI);
      tell("You carefully place the ");
      await DPRINT(g.PRSO);
      tell(" inside the dispenser.\n");
      return true;
    } else if (g.PRSO == PAPER_TOWEL) {
      move(g.PRSO, g.PRSI);
      tell("You replace the paper towel in the dispenser.\n");
      return true;
    } else {
      tell("The opening is too small and narrow for that.\n");
      return true;
    }
  } else if (isVerb(V.UNLOCK, V.MUNG, V.KICK, V.HIT)) {
    tell("Did it occur to you to simply take the towel rather than vandalizing the machine?\n");
    return true;
  } else {
    return false;
  }
}

async function PAPER_TOWEL_F() {
  if (isVerb(V.CUT, V.RIP)) {
    tell("That won't serve any purpose.\n");
    return true;
  } else if (isVerb(V.PUT, V.PUT_ON) && (g.PRSO == DOCUMENT)) {
    tell("You'd never get away with it.\n");
    return true;
  } else if (isVerb(V.TAKE, V.MOVE) && (g.PRSO == PAPER_TOWEL) && (loc(g.PRSO) == TOWEL_DISPENSER)) {
    tell("You pull out the paper towel - it's the last one.\n");
    return move(g.PRSO, g.WINNER);
  } else {
    return false;
  }
}

async function LAV_SINK_F() {
  if (isVerb(V.OPEN, V.CLOSE)) {
    tell("An odd idea.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("The sink is hideously dirty and grimy");
    if (hasFlag(LAV_FAUCET, OPENBIT)) {
      tell(", in spite of the running water");
    }
    tell("; you hesitate to even consider using it.");
    if (first(LAV_SINK)) {
      tell(" ");
      clearFlag(LAV_SINK, NDESCBIT);
      await V_EXAMINE();
      setFlag(LAV_SINK, NDESCBIT);
    } else {
      crlf();
    }
    return true;
  } else if (isVerb(V.PUT) && (g.PRSI == LAV_SINK) && (getProp(g.PRSO, P.SIZE) > 2)) {
    tell("That would only clog the drain, which won't help you, though it would make an interesting sort of statement.\n");
    return true;
  } else if (isVerb(V.PUT) && (g.PRSI == LAV_SINK) && hasFlag(LAV_FAUCET, OPENBIT)) {
    await PERFORM(V.PUT_UNDER, g.PRSO, LAV_FAUCET);
    return true;
  } else {
    return false;
  }
}

async function GLOBAL_TAIL_F() {
  if (!g.FOLLOW_WARNING) {
    tell("You don't see any particular man around here, at least none that you recognize.\n");
    return true;
  } else {
    tell("You try to find the man who appears to be tailing you, but he has gone out of sight.\n");
    return true;
  }
}

async function GLOBAL_WATER_F() {
  if (!(g.HERE == LAVATORY)) {
    tell("There's no water here.\n");
    return true;
  } else if (isVerb(V.DRINK, V.EAT)) {
    tell("You ");
    if (!(hasFlag(LAV_FAUCET, OPENBIT))) {
      tell("turn on the faucet and ");
    }
    tell("take a nice, refreshing drink, after which you turn the water back off again.\n");
    return clearFlag(LAV_FAUCET, OPENBIT);
  } else if (isVerb(V.WALK)) {
    await PERFORM(V.OPEN, LAV_FAUCET);
    return true;
  } else if (isVerb(V.ON, V.OFF, V.SET, V.OPEN, V.CLOSE)) {
    await PERFORM(g.PRSA, LAV_FAUCET);
    return true;
  } else if (isVerb(V.PUT, V.PUT_UNDER) && (g.PRSI == GLOBAL_WATER)) {
    if (!(hasFlag(LAV_FAUCET, OPENBIT))) {
      tell("There's no water running, so it'll take some time...\n");
      return true;
    } else if (g.PRSO == PAPER_TOWEL) {
      tell("You put the ");
      await DPRINT(g.PRSO);
      tell(" under the running water until it's good and wet.\n");
      move(WET_PAPER_TOWEL, loc(PAPER_TOWEL));
      await THIS_IS_IT(WET_PAPER_TOWEL);
      return remove(PAPER_TOWEL);
    } else {
      tell("There's nothing to be gained by wetting that.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function LAV_FAUCET_F() {
  if (isVerb(V.EXAMINE)) {
    tell("Like much of the rest of Frobnia, you have a choice of cold or cold running water - thus, only one faucet.");
    if (hasFlag(g.PRSO, OPENBIT)) {
      tell(" At the moment, the faucet is open and water splashes into the sink and down the drain.");
    }
    return crlf();
  } else if (isVerb(V.PUT_UNDER) && (g.PRSI == LAV_FAUCET)) {
    await PERFORM(g.PRSA, g.PRSO, GLOBAL_WATER);
    return true;
  } else if (isVerb(V.OPEN, V.ON) || (isVerb(V.SET) && !(hasFlag(g.PRSO, OPENBIT)))) {
    if (hasFlag(g.PRSO, OPENBIT)) {
      tell("The pressure is low, but the faucet is quite open.\n");
      return true;
    } else {
      setFlag(g.PRSO, OPENBIT);
      tell("You turn the faucet and the cold water starts to flow into the sink.");
      await DOWN_THE_DRAIN(LAV_SINK, 3);
      return crlf();
    }
  } else if (isVerb(V.CLOSE, V.OFF) || (isVerb(V.SET) && hasFlag(g.PRSO, OPENBIT))) {
    if (!(hasFlag(g.PRSO, OPENBIT))) {
      tell("The faucet is already closed.\n");
      return true;
    } else {
      clearFlag(g.PRSO, OPENBIT);
      tell("You turn off the faucet which, after some dripping, finally obliges.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function DOCUMENT_F() {
  if (isVerb(V.FOLD)) {
    if (getProp(g.PRSO, P.SIZE) > 4) {
      putProp(g.PRSO, P.SIZE, 2);
      tell("The document is now folded up.\n");
      return true;
    } else {
      tell("It's already folded up as much as it can be.\n");
      return true;
    }
  } else if (isVerb(V.UNFOLD)) {
    if (getProp(g.PRSO, P.SIZE) < 4) {
      tell("The document is no longer folded up.\n");
      return putProp(g.PRSO, P.SIZE, 5);
    } else {
      return await TOO_LATE();
    }
  } else if (isVerb(V.RIP, V.MUNG)) {
    tell("You ");
    if (isVerb(V.RIP)) {
      tell("rip");
    } else {
      tell("cut");
    }
    tell(" up the document into a number of pieces, leaving you with a handful of shreds.\n");
    remove(DOCUMENT);
    await THIS_IS_IT(SHREDS);
    return move(SHREDS, g.WINNER);
  } else if (isVerb(V.EXAMINE, V.READ)) {
    if (getProp(g.PRSO, P.SIZE) < 4) {
      tell("Before you start reading, you first unfold the document.\n\n");
      putProp(g.PRSO, P.SIZE, 5);
    }
    tell("It's an official document of some kind, though you can't understand a word of the contents - it's in Frobnian, naturally, so you wouldn't expect to.\n");
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE, V.LOOK_INSIDE) || (isVerb(V.PUT, V.PUT_ON) && (DOCUMENT == g.PRSI))) {
    tell("That's ridiculous.\n");
    return true;
  } else {
    return false;
  }
}

async function SHRED_F() {
  if (isVerb(V.EXAMINE, V.READ)) {
    tell("You can tell it's from the original document, though it's hard to make much of anything out of the small, wet shred of paper.\n");
    return true;
  } else {
    return false;
  }
}

async function SHREDS_F() {
  if (isVerb(V.EXAMINE, V.READ)) {
    tell("There about a dozen of them, none small enough to read which, presumably, was the idea.\n");
    return true;
  } else if (isVerb(V.EAT)) {
    tell("Just like in the movies, you eat the shreds; they don't go down easy, and you hope you won't be seeing them again.\n");
    return remove(SHREDS);
  } else if (isVerb(V.TAKE) && (loc(g.PRSO) == LAV_TOILET)) {
    tell("The shreds are wet, now. You can't take them.\n");
    return true;
  } else {
    return false;
  }
}

async function LAV_MIRROR_F() {
  if (isVerb(V.PUT_BEHIND) && (g.PRSI == LAV_MIRROR)) {
    tell("The mirror is flush with the wall.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.EXAMINE)) {
    tell("You see yourself, of course");
    if (loc(CARNATION) == BYSTANDER_CLOTHES) {
      tell(", and the mangled carnation on your lapel reminds you of your task");
    }
    tell(S(g.PERIOD_CR));
    return true;
  } else if (isVerb(V.MUNG, V.KICK)) {
    tell("There are enough vandals around without your getting into the act.\n");
    return true;
  } else {
    return false;
  }
}

async function LAV_WINDOW_F() {
  if (isVerb(V.LOOK_INSIDE)) {
    tell("You can't make out much; the window is much too grimy.\n");
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    tell("The window here doesn't open or close, which is a shame considering the not too pleasant odors contained here. The only ones that ever seem to open are those in the compartments.\n");
    return true;
  } else if (isVerb(V.CLEAN)) {
    tell("It's good that somebody thought of it, but the grime is on the outside and out of reach.\n");
    return true;
  } else if (isVerb(V.MUNG, V.KICK)) {
    tell("That would make lots of noise and bring attention to yourself, so you reconsider.\n");
    return true;
  } else {
    return false;
  }
}

