async function SIIF() {
  let ptr = 0, len = 0, flen = 0, foff = 0, fexp = 0, tmp = 0, fwrd = 0, fwlen = 0;
  ptr = get(g.OOPS_TABLE, O_CONT);
  tmp = get(g.OOPS_TABLE, O_LEN);
  loop1: for (;;) {
    if (eq(get(g.P_LEXV, ptr), W.QUOTE) || ((tmp = tmp - 1) < 0)) {
      break loop1;
    } else {
      len = len + 1;
      ptr = ptr + 2;
    }
  }
  flen = get(g.FROBNIAN, 0);
  for (;;) {
    if ((foff = foff + 1) > flen) {
      if (g.BUMPER_FLAG) {
        tell("The ");
        await DPRINT(g.BUMPER_FLAG);
        tell(" looks confused. It doesn't appear that your Frobnian has made a big impression.\n");
        g.BAD_SPEAKING = true;
        await BAD_ARREST$();
      } else {
        tell(S(g.NO_FROBNIAN), "\n");
      }
      return true;
    } else {
      fexp = get(g.FROBNIAN, foff);
      if (eq(fwlen = get(fwrd = get(fexp, 0), 0), len)) {
        tmp = 0;
        ptr = get(g.OOPS_TABLE, O_CONT);
        loop3: for (;;) {
          if ((tmp = tmp + 1) > fwlen) {
            tmp = -1;
            break loop3;
          } else if (eq(get(fwrd, tmp), get(g.P_LEXV, ptr))) {
            ptr = ptr + 2;
          } else {
            break loop3;
          }
        }
        if (tmp < 0) {
          foff = -1;
        }
      }
    }
    if (foff < 0) {
      await apply(get(fexp, 1));
      return true;
    }
  }
}

