async function I_ASSASSINATION() {
  highlight(H_BOLD);
  crlf();
  if (g.HERE == SNIPER_ROOM) {
    return (await JIGS_UP("The sniper squeezes the trigger twice, and the sound echoes through the room. Your agents have chosen well - Huttinger is dead, and you have failed in your mission."));
  } else if (await SQUARE_VIEW$()) {
    return (await JIGS_UP("A shot rings out, then another. The sound echoes through the square, followed by a different one, the sound of screams, then sirens. Police run onto the dais, as the body of the American ambassador is carried off on a stretcher. By instinct, you know he is already dead."));
  } else {
    return (await JIGS_UP("In the direction of the square, you hear the sound of shots being fired. You needn't be told what has happened - your agents are quite thorough - the ambassador is dead."));
  }
}

