async function COUNTER_ENTER() {
  tell("You approach the counter ");
  if (loc(CUSTOMER) == ANTIQUE_SHOP) {
    tell("and the proprietor turns away anxiously.\n");
    g.P_WALK_DIR = false;
    await PERFORM(V.TELL, CUSTOMER);
    return false;
  } else {
    g.ANTIQUE_FLAG = true;
    tell("and the proprietor comes out from behind it to greet you. \"Welcome, my friend! How may I assist you? A clock, perhaps? A music box?\" He smiles warmly, but, sensing your urgency, stops abruptly. \"You are right to look worried. I am being watched. We must be very careful now.\" You talk quickly, giving him a condensed version of what has happened, and why you are in need of information. He nods grimly, and draws closer. \"Then the businessman on the train must have smuggled the document across the border. You've seen the extra security, no doubt - the authorities must know about our plan! The 'event' is at noon, as the ambassador is speaking to the crowd. If you're going to get near our sniper, you'll need the password - \"");
    tell(S(get(g.SNIPER_PASSWORD_TBL, g.SNIPER_CODE)));
    tell("\"; he is positioned in a window on the...\n\nAt just this moment, two uniformed policemen enter. \"You must go. Through the back!\" He shoves you forcibly through the door to the back room as the men approach.\n\nThe back room itself is small, dark, and cluttered. It's hard to tell the difference, in fact, between what lies out front and what lies in here. The door to the counter area is slightly ajar, and through it you can hear the police questioning your friend. He's doing his best, but they are persistent. It is not safe here any longer; the door to the street lies to the west.");
  }
  await RT_QUEUE(I_POLICE_ENTER.id, 95);
  crlf();
  g.DONT_DESCRIBE_ROOM = true;
  if (g.CHASE_FLAG) {
    tell("\nA moment later, Topaz bursts into the shop and alerts the police to your presence. Despite the protests of Riznik, they enter and take you into custody.\n");
    await JIGS_UP(g.EPILOGUE_BAD_FAILS);
  }
  return ANTIQUE_STORAGE;
}

