async function ELEVATOR_ROOM_F(rarg) {
  if (rarg == M_ENTER) {
    await STATUS_LINE();
    await DE_QUEUE(I_ELEVATOR_OFF);
    tell("The elevator operator says, \"Which floor, please?\"\n\n");
    if (g.CHASE_FLAG) {
      if (g.HALL_FLOOR > 1) {
        if (hasFlag(loc(TOPAZ), PENBIT)) {
          tell("At this moment, Topaz pulls himself through the window at the far end of the hall. Fearful that you are about to give him the slip, he");
        } else {
          tell("Topaz, still down the hall and fearful that you are about to give him the slip,");
        }
        tell(" pulls out his revolver and fires twice, hitting you in the shoulder and leg. Wounded, but not seriously, you are taken to police headquarters, where you are treated and questioned.\n");
      } else {
        tell("At this moment, Topaz bursts into the lobby, and motions to the police guards, who respond by grabbing you. Clearly, they are well aware of Topaz's identity. After a brief discussion between them, you are hustled off for questioning.\n");
      }
      await JIGS_UP(g.EPILOGUE_BAD_FAILS);
    }
    if (await ELEVATOR_SEQUENCE()) {
      tell("The operator closes the door, and the elevator slowly ");
      if (g.P_NUMBER > g.HALL_FLOOR) {
        tell("climb");
      } else {
        tell("descend");
      }
      tell("s to the ");
      tell(S(get(g.CARDINALS, g.P_NUMBER)));
      tell(" floor; having arrived, the operator opens the door and hustles you out the door.");
      if (!(g.P_NUMBER == 1)) {
        tell(" The elevator departs, presumably for the ground floor.");
      }
      tell("\n\n");
      g.CLOCK_MOVE = 15 + ((await ABS(g.P_NUMBER - g.HALL_FLOOR)) * 5);
      g.HALL_FLOOR = g.P_NUMBER;
      if (g.P_NUMBER == 1) {
        await GOTO(APARTMENT_LOBBY);
        return setFlag(ELEVATOR_DOOR, OPENBIT);
      } else {
        clearFlag(ELEVATOR_DOOR, OPENBIT);
        return await GOTO(HALL_4);
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function ELEVATOR_SEQUENCE() {
  let ptr = 0;
  restart: for (;;) {
    print(">>");
    putb(g.P_INBUF, 1, 0);
    await read(g.P_INBUF, g.P_LEXV);
    ptr = 1;
    if ((await NUMBER$(ptr)) && (g.P_NUMBER > 0) && (g.P_NUMBER < 6)) {
      if (g.HALL_FLOOR == g.P_NUMBER) {
        tell("\"We are already there, sir.\" She escorts you off the elevator.\n");
        if (g.HALL_FLOOR == 1) {
          await GOTO(APARTMENT_LOBBY, false);
        } else {
          await GOTO(HALL_4, false);
        }
        return false;
      } else {
        return true;
      }
    } else {
      tell("\"Please tell me the floor you wish to go to, from 1 to 5.\"");
      crlf();
      crlf();
      continue restart;
    }
  }
}

