async function HALL_DOOR_F() {
  if (isVerb(V.SHOOT)) {
    tell("Risky at best; suicidal at worst.\n");
    return true;
  } else if ((g.PRSO == HALL_DOOR_W) || !(g.HALL_FLOOR == g.SNIPER_FLOOR) || !(g.HERE == g.SNIPER_HALL || g.HERE == SNIPER_ROOM) || (!(g.HERE == SNIPER_ROOM) && (g.CLOCK_TIME > 1000))) {
    if (isVerb(V.KNOCK)) {
      tell("You wait for a few seconds, but there is no answer.\n");
      return g.CLOCK_MOVE = 20;
    } else if (isVerb(V.LISTEN)) {
      tell("You can't hear anything from inside the apartment; if the sniper were a pro, you probably wouldn't hear him anyway.\n");
      return true;
    } else if (isVerb(V.OPEN, V.UNLOCK, V.KICK)) {
      tell("Rather unsubtle, don't you think. Surely you can think of something less likely to get you embarrassed or killed.\n");
      return true;
    } else if (isVerb(V.EXAMINE)) {
      return await TELL_ROOM_NUMBER();
    } else {
      return false;
    }
  } else if (g.HERE == SNIPER_ROOM) {
    if (isVerb(V.EXAMINE)) {
      tell("The door is closed and locked from the inside.\n");
      return true;
    } else if (isVerb(V.OPEN, V.UNLOCK) && (loc(SNIPER) == g.HERE)) {
      tell("You move slowly toward the door, but the sniper's senses are sharper than your own. \"Please stay away from the door. There are enemy agents all around us; we must be on our guard!\" Backing away from the door, you find yourself thinking that your choices are few and unpleasant.\n");
      return true;
    } else if (isVerb(V.HIDE_BEHIND)) {
      if (g.HIDING_BEHIND_DOOR) {
        return await TOO_LATE();
      } else {
        g.HIDING_BEHIND_DOOR = true;
        tell("You move back toward the door a few feet; not enough to alarm the sniper, but enough to be out of the line of fire, should it come to that.\n");
        return true;
      }
    } else if (isVerb(V.LISTEN)) {
      tell("You can't hear anything from the hallway.\n");
      return true;
    } else if (isVerb(V.KNOCK)) {
      tell("You think twice; the sniper would probably kill you first.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.EXAMINE)) {
    return await TELL_ROOM_NUMBER();
  } else if (isVerb(V.KICK)) {
    tell("This would no doubt alert the sniper, with dangerous results.\n");
    return true;
  } else if (isVerb(V.LISTEN)) {
    tell("You can't hear anything from inside the apartment; if the sniper were a pro, you probably wouldn't hear him anyway.\n");
    return true;
  } else if (isVerb(V.OPEN)) {
    tell("You try the knob - the door is locked.\n");
    return true;
  } else if (isVerb(V.KNOCK) && !g.AWAITING_PASSWORD) {
    g.AWAITING_PASSWORD = g.CLOCK_TIME;
    tell("There is a brief pause, then a heavily accented voice answers. There is a distinct tension in his voice as he says \"Say the word, please. Quickly!\"\n");
    return true;
  } else if (isVerb(V.KNOCK)) {
    tell("There is no answer. Your delay in answering the sniper puts you in a very dangerous position.\n");
    return true;
  } else {
    return false;
  }
}

async function CHECK_PASSWORD() {
  if (g.AWAITING_PASSWORD && ((g.CLOCK_TIME - g.AWAITING_PASSWORD) < 100)) {
    if (eq(get(g.P_LEXV, get(g.OOPS_TABLE, O_CONT)), get(g.SNIPER_PASSWORD_VOC, g.SNIPER_CODE))) {
      tell("The door opens slightly, and a small, dark man answers. He waves a pistol in your direction, and glances both ways down the hall. ");
      if (hasFlag(loc(TOPAZ), HUTBIT)) {
        return (await JIGS_UP("Seeing that you have been followed, he screams with rage, \"You have betrayed us!\" Without a moment's hesitation, he pulls the trigger, ending your life."));
      } else {
        tell("Satisfied that you were not followed, he motions you into the room. Again, reassuring himself that you weren't followed, he ");
        if (await SNIPER_SPOTS$()) {
          tell("picks up the items on the ground, moves them into his room, ");
        }
        tell("closes and locks the door, then walks back to the window. \"There is not much time,\" he says, blankly.");
        tell("\n\nThe apartment is bare of all furniture. Kneeling in the window, perfectly motionless, the sniper eyes his target through the sights of his high-powered rifle.\n");
        await GOTO(SNIPER_ROOM, false);
        return true;
      }
    } else {
      tell("There is no reply, though you can hear a faint shuffling of feet through the door.\n");
      return true;
    }
  } else if (g.AWAITING_PASSWORD) {
    tell("There is only silence coming from within the room.\n");
    return true;
  } else {
    tell("Nobody here seems interested in your words.\n");
    return true;
  }
}

async function SNIPER_SPOTS$() {
  let obj = 0, off = 0, f = 0, n_ = 0, flg = false;
  f = first(g.SNIPER_HALL);
  loop1: for (;;) {
    if (!f) {
      break loop1;
    } else {
      n_ = next(f);
      if ((getProp(f, P.SIZE) > 2) && !(f == PROTAGONIST)) {
        flg = true;
        break loop1;
      }
    }
    f = n_;
  }
  if (flg) {
    await MOVE_ALL(g.SNIPER_HALL, SNIPER_ROOM);
    return true;
  } else {
    return false;
  }
}

async function MOVE_ALL(from, to) {
  let f = 0, n_ = 0;
  f = first(from);
  for (;;) {
    if (!f) {
      return true;
    } else {
      n_ = next(f);
      move(f, to);
    }
    f = n_;
  }
}

